PROG2.mixo={n:'I – ♭VII – IV (mixolidio)',it:[[0,'maj'],[10,'maj'],[5,'maj'],[0,'maj']],sc:'mix',tip:'Mixolidio: escala mayor con la 7ª un semitono abajo.'};
PROG2.lidio={n:'I – II (lidio)',it:[[0,'maj'],[2,'maj']],sc:'lyd',tip:'Lidio: escala mayor con la 4ª un semitono arriba.'};
SCALES2.mix={semis:[0,2,4,5,7,9,10],n:'Mixolidio'};
SCALES2.lyd={semis:[0,2,4,6,7,9,11],n:'Lidio'};
const nm=pc=>PCS[pc][0];
const pts=(arr,o)=>({type:'seq',arr,o:o||{}});
const bySound=a=>a.slice().sort((x,y)=>(OPEN_MIDI[x[0]]+x[1])-(OPEN_MIDI[y[0]]+y[1]));
const natOn=st=>pts(pos([0,2,4,5,7,9,11],0,12).filter(([s])=>s===st).sort((a,b)=>a[1]-b[1]).map(([s,f])=>[s,f,null,f===0||f===12?'root':'note']));
const boxFig=(k,sc,p,to,range)=>{const D=pentaData({k,sc,p,b:0});let ds=D.dots.filter(d=>d.k!=='faint');if(range)ds=D.dots.filter(d=>d.f>=range[0]&&d.f<=range[1]).map(d=>Object.assign({},d,{k:d.k==='faint'?'note':d.k}));return pts(bySound(ds.map(d=>[d.s,d.f,d.t,d.k==='root'?'root':'note'])),{to:to||17,zones:range?[range]:D.zones})};
const chords=(list,beats)=>({type:'chords',list,beats:beats||4});
const CH={C:[null,3,2,0,1,0],Cmaj7:[null,3,2,0,0,0],C7:[null,3,2,3,1,0],Dm:[null,null,0,2,3,1],Dm7:[null,null,0,2,1,1],D:[null,null,0,2,3,2],D7:[null,null,0,2,1,2],Dsus4:[null,null,0,2,3,3],E:[0,2,2,1,0,0],Em:[0,2,2,0,0,0],Em7:[0,2,0,0,0,0],F:[1,3,3,2,1,1],Fmaj7:[null,null,3,2,1,0],G:[3,2,0,0,0,3],G7:[3,2,0,0,0,1],A:[null,0,2,2,2,0],Am:[null,0,2,2,1,0],Am7:[null,0,2,0,1,0],Asus2:[null,0,2,2,0,0],Bdim:[null,2,3,4,3,null],Bm7b5:[null,2,3,2,3,null],Bb:[null,1,3,3,3,1],Eb:[null,6,8,8,8,6]};
const ch=(...names)=>names.map(n=>[n.replace('b5','♭5').replace('Bb','B♭').replace('Eb','E♭').replace('dim','°'),CH[n]]);
const E=(o)=>({ex:o});
const LESSONS=[
{id:1,part:1,title:'El mástil deja de ser un laberinto',sub:'Las 12 notas, cómo contarlas y cómo ubicarlas rápido',
 lead:'Con dos reglas (un traste = un semitono, y solo hay 12 notas) puedes nombrar cualquier punto del mástil.',
 blocks:[
 {aim:['Saber cómo se llama cada cuerda al aire.','Entender qué es un traste y qué es un semitono.','Conocer las 12 notas y por qué entre Mi–Fa y Si–Do no hay nota en medio.','Encontrar cualquier nota natural en las cuerdas 6 y 5 contando trastes.','Usar la forma de octava para encontrar la misma nota en otra cuerda.']},
 {step:'Paso 1',t:'Cómo se llaman las cuerdas',p:'Las cuerdas se numeran de la más delgada (abajo, cerca del piso) a la más gruesa (arriba): la <b>cuerda 1</b> es la delgada y la <b>cuerda 6</b> la gruesa. Tocadas al aire, sin pisar, suenan así: <span class="hl">6 = Mi, 5 = La, 4 = Re, 3 = Sol, 2 = Si, 1 = Mi</span>. Una frase para recordarlas: «<b>Mi</b> <b>La</b>drón <b>Re</b>gresa <b>Sol</b>o <b>Si</b> <b>Mi</b>ro». Fíjate que las cuerdas 6 y 1 son las dos Mi: la 1 suena igual pero más aguda. En el cifrado americano, que verás en canciones, Do Re Mi Fa Sol La Si se escriben C D E F G A B.'},
 {step:'Paso 2',t:'Un traste es un semitono',p:'Cada traste que avanzas hacia el cuerpo de la guitarra sube el sonido <b>un semitono</b>, el paso más pequeño de la música occidental. Dos trastes son un <b>tono</b>. No importa la cuerda: la regla es la misma en las seis. Ejemplo: la cuerda 5 al aire es La; en el traste 1 suena La♯; en el traste 2, Si. Por eso, para saber qué nota tocas, solo necesitas saber la nota de la cuerda al aire y contar trastes.'},
 {step:'Paso 3',t:'Solo hay 12 notas',p:'Si sigues subiendo de semitono en semitono pasas por 12 notas y luego se repite la primera, más aguda: <span class="hl">Do, Do♯, Re, Re♯, Mi, Fa, Fa♯, Sol, Sol♯, La, La♯, Si</span>… y otra vez Do. Siete tienen nombre propio, son las <b>naturales</b> (Do Re Mi Fa Sol La Si); las otras cinco llevan <b>♯ (sostenido)</b>, que significa «un semitono arriba de». La misma nota también se puede llamar con <b>♭ (bemol)</b>, «un semitono abajo de»: Do♯ y Re♭ suenan igual. Como son 12 notas, <b>en el traste 12 la cuerda vuelve a sonar como al aire</b>, una octava más aguda: el mástil se repite.'},
 {key:'Entre <b>Mi y Fa</b>, y entre <b>Si y Do</b>, la distancia es de un solo semitono: no hay ninguna nota en medio (si escribes Mi♯, suena igual que Fa). Entre todas las demás naturales hay un tono, con un sostenido en medio. Con esto ya puedes contar cualquier cuerda.'},
 {step:'Paso 4',t:'Ejemplo resuelto: la cuerda 6 nota por nota',p:'La cuerda 6 al aire es Mi. Mi → Fa es un semitono: <b>Fa en el traste 1</b>. Fa → Sol es un tono: <b>Sol en el 3</b>. Sol → La, un tono: <b>La en el 5</b>. La → Si, un tono: <b>Si en el 7</b>. Si → Do es semitono: <b>Do en el 8</b>. Do → Re, un tono: <b>Re en el 10</b>. Re → Mi, un tono: <b>Mi en el 12</b>, la cuerda al aire otra vez. Quedan así: Mi 0, Fa 1, Sol 3, La 5, Si 7, Do 8, Re 10, Mi 12. Los huecos (2, 4, 6, 9, 11) son los sostenidos.'},
 {w:'noteFinder'},
 E({id:'1a',t:'Las naturales de la cuerda 6',min:3,steps:['Toca la cuerda 6 al aire y di en voz alta «Mi». Usa el dedo 1 para pisar cada traste, justo detrás del alambre.','Sube nombrando solo las naturales: Mi (0), Fa (1), Sol (3), La (5), Si (7), Do (8), Re (10), Mi (12). Usa el botón › del diagrama para verlas una por una.','Baja del traste 12 al 0 con los mismos nombres.','Ahora sin ver el diagrama: guíate por los puntos del mástil (3, 5, 7 y 12).'],goal:'Nombras las ocho posiciones de ida y vuelta sin detenerte.',fig:natOn(6)}),
 {step:'Paso 5',t:'La cuerda 5 con la misma regla',p:'La cuerda 5 al aire es La. Aplica la regla: La → Si (tono) = <b>traste 2</b>; Si → Do (semitono) = <b>3</b>; Do → Re = <b>5</b>; Re → Mi = <b>7</b>; Mi → Fa (semitono) = <b>8</b>; Fa → Sol = <b>10</b>; Sol → La = <b>12</b>. Con las cuerdas 6 y 5 tienes la base de casi todos los acordes con cejilla y de las escalas que verás después, porque la nota más grave de un acorde suele estar en una de estas dos cuerdas.'},
 E({id:'1b',t:'Lo mismo en la cuerda 5',min:3,steps:['Cuerda 5 al aire: La.','Sube: La (0), Si (2), Do (3), Re (5), Mi (7), Fa (8), Sol (10), La (12).','Fíjate en los dos saltos de un solo traste: Si–Do (2–3) y Mi–Fa (7–8).','Alterna: una nota en la cuerda 6 y la misma nota en la cuerda 5 (por ejemplo Do: 6/8 y 5/3).'],goal:'Encuentras cualquier natural de las cuerdas 6 y 5 en menos de dos segundos.',fig:natOn(5)}),
 {check:[['¿Qué nota suena en la cuerda 5, traste 7?','Mi. La (0) → Si (2) → Do (3) → Re (5) → Mi (7).'],['¿En qué traste de la cuerda 6 está Do?','En el traste 8.'],['¿Por qué Mi y Fa están en trastes seguidos (0 y 1 en la cuerda 6)?','Porque entre Mi y Fa hay un solo semitono: no hay nota en medio.'],['¿Qué nota suena en el traste 12 de cualquier cuerda?','La misma que al aire, una octava más aguda.']]},
 {step:'Paso 6',t:'Puntos de referencia para no contar desde cero',p:'Contar desde el traste 0 cada vez es lento. Usa los puntos que trae el mástil en los trastes 3, 5, 7, 9 y 12 como señales. Memoriza solo unas cuantas: en la cuerda 6, <b>traste 5 = La</b> y <b>traste 8 = Do</b>; en la cuerda 5, <b>traste 3 = Do</b> y <b>traste 5 = Re</b>. Desde ahí cuenta uno o dos trastes. Truco extra: el traste 5 de una cuerda suena igual que la siguiente cuerda al aire (6/5 = La = cuerda 5 al aire). Así se afina la guitarra de oído, y solo falla entre las cuerdas 3 y 2, donde es el traste 4.'},
 {w:'octave'},
 {step:'Paso 7',t:'La forma de octava',p:'Una <b>octava</b> es la misma nota, más aguda: 12 semitonos arriba. En la guitarra la encuentras con una forma fija, sin contar. Desde las cuerdas 6 o 5: <span class="hl">sube dos cuerdas y dos trastes</span> (Fa en 6/1 → Fa en 4/3). Desde las cuerdas 4 o 3: <span class="hl">sube dos cuerdas y tres trastes</span> (Re en 4/0 → Re en 2/3). ¿Por qué cambia? Porque entre las cuerdas 3 y 2 la distancia es un semitono más corta que entre las demás, así que al cruzarla hay que subir un traste más para compensar. Cada nota que conozcas te regala otra en una cuerda más aguda.'},
 E({id:'1c',t:'Octavas al pulso',min:4,bpm:60,steps:['Toca Fa en la cuerda 6 (traste 1, dedo 1) en el tiempo 1 y su octava en la cuerda 4 (traste 3, dedo 3) en el tiempo 3. Apaga la cuerda 5 apoyando suave el dedo 1.','Sigue con Sol y La: un par por compás, la mano no cambia de forma.','Repite desde la cuerda 5: La (0) con La en la cuerda 3 (traste 2), y sigue subiendo.','Usa el paso a paso (›) si no ves qué dedo va. Cuando salga limpio, sube el metrónomo a 72.'],goal:'Recorres seis octavas seguidas sin perder el pulso.',fig:pts([[6,1,'Fa','root'],[4,3,'Fa'],[6,3,'Sol','root'],[4,5,'Sol'],[6,5,'La','root'],[4,7,'La']])}),
 E({id:'1d',t:'Juego: encuentra la nota',min:2,steps:['Abre el juego con el botón de abajo (trastes 0 a 5, solo naturales).','Toca en el mástil la nota que aparece arriba, tantas veces como puedas en un minuto.','Juégalo de nuevo y trata de superar tu récord.'],goal:'Logras 15 aciertos en un minuto.',game:{mode:'find',range:5,str:0,nat:1}}),
 E({id:'1e',t:'Una nota en las seis cuerdas',min:4,bpm:50,steps:['Elige Sol y tócalo en la cuerda 6 (traste 3).','Octava: cuerda 4, traste 5. Al aire: cuerda 3. Desde la cuerda 4/5, otra octava: cuerda 2, traste 8. Y la cuerda 1, traste 3, es igual que la 6.','Con el paso a paso (›) ve cada Sol de grave a agudo, un toque por pulso.','Repite con La, Do y Re diciendo en voz alta la cuerda y el traste de cada uno.'],goal:'Encuentras cualquier nota en las seis cuerdas en menos de 15 segundos.',fig:pts([[6,3,'Sol','root'],[5,10,'Sol'],[4,5,'Sol'],[3,0,'Sol'],[2,8,'Sol'],[1,3,'Sol']])}),
 {check:[['Si encuentras La en la cuerda 6, traste 5, ¿dónde está su octava?','En la cuerda 4, traste 7 (dos cuerdas y dos trastes arriba).'],['Re está en la cuerda 4 al aire. ¿Dónde está su octava?','En la cuerda 2, traste 3 (desde la cuerda 4 se suben tres trastes).'],['¿Qué nota es el traste 5 de la cuerda 6, y qué cuerda al aire suena igual?','La; suena igual que la cuerda 5 al aire.']]},
 {box:'Errores comunes',ul:['Aprender las notas solo cuerda por cuerda: usa las octavas para saltar de una cuerda a otra.','Olvidar que el traste 12 repite la cuerda al aire.','Creer que entre Mi y Fa o entre Si y Do falta un sostenido: no existe, es un semitono.','Usar la forma de octava de dos trastes desde las cuerdas 4 o 3: desde ahí son tres trastes.','Pisar en medio del traste: el dedo va justo detrás del alambre, así suena limpio con menos fuerza.']},
 {trick:['Cuerdas al aire, de la 6 a la 1: Mi La Re Sol Si Mi.','1 traste = 1 semitono · 2 trastes = 1 tono.','Mi–Fa y Si–Do: semitono, sin nota en medio.','Traste 12 = la cuerda al aire, una octava arriba.','Cuerda 6: La 5, Do 8 · cuerda 5: Do 3, Re 5.','Octava: desde 6 y 5 sube 2 cuerdas y 2 trastes; desde 4 y 3, 2 cuerdas y 3 trastes.','Do Re Mi Fa Sol La Si = C D E F G A B.']}]},
{id:2,part:1,title:'Intervalos: la distancia es la emoción',sub:'Cómo medir, ver y oír la distancia entre dos notas',
 lead:'Un intervalo es la distancia entre dos notas. Cada distancia tiene su propio sabor, y en la guitarra cada una tiene una forma fija.',
 blocks:[
 {aim:['Medir cualquier intervalo contando trastes (la nota de partida es el cero).','Conocer los nombres de los 12 intervalos y su sonido.','Ver las formas de los intervalos en una cuerda y entre cuerdas vecinas.','Entender la excepción entre las cuerdas 3 y 2.','Tocar power chords sabiendo por qué suenan así.']},
 {step:'Paso 1',t:'Qué es un intervalo y cómo se mide',p:'Un <b>intervalo</b> es la distancia entre dos notas, medida en semitonos. Como en la guitarra un traste es un semitono, medir es contar trastes. La regla de oro: <span class="hl">la nota de partida es el cero</span>, no el uno. Ejemplo: de Do (cuerda 5, traste 3) a Mi (cuerda 5, traste 7) hay 7 − 3 = <b>4 semitonos</b>. Si cuentas «3, 4, 5, 6, 7» te salen cinco números, pero son cuatro saltos. Siempre resta: traste final menos traste inicial.'},
 {step:'Paso 2',t:'Los nombres: un número y un apellido',p:'Cada intervalo se nombra con un número, que dice cuántas letras abarca (Do–Mi abarca Do, Re, Mi = tercera), y un apellido que dice su tamaño exacto: <b>menor</b>, <b>mayor</b> o <b>justa</b>. La tabla completa, en semitonos: <span class="hl">1 = 2ª menor · 2 = 2ª mayor · 3 = 3ª menor · 4 = 3ª mayor · 5 = 4ª justa · 6 = tritono · 7 = 5ª justa · 8 = 6ª menor · 9 = 6ª mayor · 10 = 7ª menor · 11 = 7ª mayor · 12 = octava</span>. No hace falta memorizarla hoy: los que más vas a usar son la 3ª menor (3), la 3ª mayor (4), la 4ª justa (5), la 5ª justa (7) y la octava (12).'},
 {step:'Paso 3',t:'Cada distancia tiene un carácter',p:'Las distancias no solo se cuentan, se sienten. La <b>3ª menor</b> suena triste u oscura; la <b>3ª mayor</b>, alegre o luminosa. Esa sola diferencia de un traste es lo que separa un acorde menor de uno mayor (lección 5). La <b>5ª justa</b> y la <b>4ª justa</b> suenan abiertas y estables: son la base del rock. El <b>tritono</b> (6) suena tenso, como si pidiera moverse a otro lado; por eso los acordes de séptima «empujan» hacia otro acorde. La <b>2ª menor</b> (1) choca: es el sonido de suspenso de las películas.'},
 {w:'intervals'},
 E({id:'2a',t:'Terceras sobre una cuerda',min:3,bpm:60,steps:['Toca Do en la cuerda 5, traste 3, con el dedo 1.','Tercera menor: tres trastes arriba (traste 6, Mi♭) con el dedo 4. Regresa a Do.','Tercera mayor: cuatro trastes arriba (traste 7, Mi). Regresa a Do. Usa el paso a paso (›) para ver cada nota.','Alterna menor y mayor, un toque por pulso, y di en voz alta «triste» o «alegre».'],goal:'Distingues las dos terceras con los ojos cerrados.',fig:pts([[5,3,'Do','root'],[5,6,'♭3'],[5,7,'3']])}),
 {check:[['¿Cuántos semitonos hay del traste 5 al traste 9 de la misma cuerda?','Cuatro (9 − 5): una tercera mayor.'],['¿Qué intervalo son 7 semitonos?','Una quinta justa.'],['¿Por qué no se cuenta el traste de la nota de partida?','Porque es el punto de partida (el cero): contamos saltos, no notas.']]},
 {step:'Paso 4',t:'Intervalos entre dos cuerdas',p:'Tocar todo en una cuerda obliga a estirar la mano. Por eso conviene ver las formas entre cuerdas vecinas. Las cuerdas de la guitarra están afinadas a una <b>4ª justa</b> de distancia (5 semitonos), así que: <span class="hl">mismo traste en la cuerda de abajo = 4ª justa</span>; <span class="hl">dos trastes más = 5ª justa</span>; <span class="hl">un traste menos = 3ª mayor</span>; <span class="hl">dos trastes menos = 3ª menor</span>. Ejemplo resuelto: raíz Sol en la cuerda 6, traste 3. Su quinta (Re) está en la cuerda 5, traste 5; su cuarta (Do), en la cuerda 5, traste 3; su tercera mayor (Si), en la cuerda 5, traste 2.'},
 {key:'La única excepción está entre las cuerdas <b>3 y 2</b>: esas dos están afinadas a una 3ª mayor (4 semitonos), uno menos que las demás. Por eso, cuando una forma cruza de la cuerda 3 a la 2, <b>todo lo que está en la cuerda 2 se corre un traste hacia arriba</b>. Es la misma razón por la que la octava desde las cuerdas 4 y 3 sube tres trastes (lección 1).'},
 E({id:'2c',t:'Cuartas apiladas',min:2,steps:['Toca el traste 5 de las cuerdas 6, 5, 4 y 3: La, Re, Sol y Do. Cada una es una cuarta justa más aguda que la anterior.','En la cuerda 2 usa el traste 6 (Fa), no el 5: así sigue siendo una cuarta. Esa es la excepción.','Compara: toca la cuerda 2 en el traste 5 y escucha que ya no suena igual de «abierto».','Así se afina la guitarra de oído: traste 5 contra la siguiente cuerda al aire, y traste 4 entre las cuerdas 3 y 2.'],goal:'Explicas por qué la cuerda 2 se corre un traste.',fig:pts([[6,5],[5,5],[4,5],[3,5],[2,6]],{to:8})}),
 {step:'Paso 5',t:'El power chord: raíz y quinta',p:'Un <b>power chord</b> (acorde de quinta, se escribe Sol5, Do5…) son solo dos notas: la raíz y su 5ª justa, a veces con la octava encima. Como no tiene tercera, <b>no es mayor ni menor</b>: suena neutro y fuerte, y por eso funciona con distorsión, donde las terceras se ensucian. La forma: raíz en la cuerda 6 o 5 con el dedo 1, quinta en la cuerda de abajo dos trastes arriba con el dedo 3, y la octava en la siguiente cuerda, mismo traste, con el dedo 4. Para cambiar de acorde mueve toda la mano sin cambiar la forma.'},
 E({id:'2b',t:'Quintas: el power chord',min:4,bpm:80,steps:['Raíz en la cuerda 6 (dedo 1) y quinta en la cuerda 5, dos trastes arriba (dedo 3).','Toca Mi5 (0–2), Sol5 (3–5), La5 (5–7) y Do5 (8–10): dos golpes por acorde. Solo suenan esas dos cuerdas: apaga las demás con la palma o con la yema del dedo 1.','Añade la octava en la cuerda 4, mismo traste que la quinta, con el dedo 4.','Repite con la raíz en la cuerda 5: Re5 (5–7), Mi5 (7–9) y Sol5 (10–12).'],goal:'Cambias entre los cuatro power chords sin perder un golpe.',fig:pts([[6,3,'1','root'],[5,5,'5'],[4,5,'8']],{to:7})}),
 {step:'Paso 6',t:'Oír los intervalos',p:'Ver la forma no basta: el objetivo es reconocer la distancia de oído. Un truco que usan los músicos es asociar cada intervalo con el inicio de una canción conocida. El inicio de «Estrellita» (Do–Do–<b>Sol</b>–Sol) salta una <b>5ª justa</b>. «Cumpleaños feliz» (Sol–Sol–La–Sol–<b>Do</b>) sube de Sol a Do, una <b>4ª justa</b>. Una <b>octava</b> es el salto del inicio de «Somewhere over the rainbow». Busca tus propias canciones para cada intervalo y canta antes de tocar.'},
 E({id:'2d',t:'Canta antes de tocar',min:3,steps:['Toca una raíz y, sin tocar nada más, canta la tercera mayor (piensa en lo alegre).','Comprueba tocándola: cuatro trastes arriba en la misma cuerda.','Repite con la quinta (piensa en «Estrellita»), la cuarta («Cumpleaños feliz») y la octava.','Usa el diagrama de intervalos de arriba para escuchar los que dudes.'],goal:'Aciertas cuatro de cinco intervalos cantados.'}),
 {check:[['Raíz La en la cuerda 6, traste 5. ¿Dónde está su quinta en la cuerda 5?','En el traste 7 (mismo traste + 2).'],['¿Qué intervalo hay entre la cuerda 4 al aire (Re) y la cuerda 3 al aire (Sol)?','Una cuarta justa: así están afinadas casi todas las cuerdas.'],['¿Por qué un power chord no es ni mayor ni menor?','Porque no tiene tercera: solo raíz y quinta.'],['Si una forma cruza de la cuerda 3 a la 2, ¿qué pasa?','La nota de la cuerda 2 se corre un traste hacia arriba.']]},
 {box:'Errores comunes',ul:['Contar el traste de la raíz como uno: la raíz es el cero.','Confundir cuarta aumentada y quinta disminuida: suenan igual (tritono) y cambian de nombre según el contexto.','Olvidar la excepción entre las cuerdas 3 y 2.','Dejar sonar cuerdas de más en el power chord: apágalas con la mano.','Aprender solo la forma o solo el oído: combina ambos.']},
 {trick:['La raíz es el cero: resta traste final menos traste inicial.','3ª menor = 3 · 3ª mayor = 4 · 4ª = 5 · 5ª = 7 · octava = 12 semitonos.','Misma cuerda: +3 trastes = 3ª menor; +4 = 3ª mayor.','Cuerda de abajo: mismo traste = 4ª; +2 = 5ª; −1 = 3ª mayor; −2 = 3ª menor.','Entre las cuerdas 3 y 2 todo se corre un traste.','Oído: menor = triste, mayor = alegre, 5ª = abierta, tritono = tenso.']}]},
{id:3,part:2,title:'Escalas y tonalidades: la regla madre',sub:'Una receta para las doce tonalidades',
 lead:'Aprende la receta de la escala mayor, tócala con una forma que cabe en tu mano y muévela a cualquier tono.',
 blocks:[
 {aim:['Saber qué es un tono y un semitono en la guitarra.','Armar la escala mayor desde cualquier nota con una sola receta.','Tocarla con una forma de dedos que puedes mover a cualquier tonalidad.','Usar números (grados) para tocar la misma melodía en otro tono.']},
 {step:'Paso 1',t:'Tono y semitono: las dos medidas',p:'En la guitarra las distancias se miden en trastes. <span class="hl">Un semitono es un traste</span> y <span class="hl">un tono son dos trastes</span>. Ejemplo: en la cuerda 5, del traste 3 al 4 hay un semitono; del traste 3 al 5 hay un tono. Con solo estas dos medidas se arman todas las escalas.'},
 E({id:'3s',t:'Siente el semitono y el tono',min:2,bpm:60,steps:['Pon el dedo 1 en la cuerda 5, traste 3 (es Do).','Sube un traste (traste 4): eso es un semitono. Regresa al 3.','Ahora sube dos trastes (traste 5): eso es un tono. Regresa al 3.','Alterna semitono y tono diciendo en voz alta «semi» o «tono».'],goal:'Sabes, sin contar, si un salto es de uno o de dos trastes.',fig:pts([[5,3,'Do','root'],[5,4,'S'],[5,3,'Do','root'],[5,5,'T']],{to:6})}),
 {step:'Paso 2',t:'La receta de la escala mayor',p:'La escala mayor es la de «do-re-mi-fa-sol-la-si-do». Para armarla desde cualquier nota se siguen siempre los mismos saltos: <span class="hl">tono, tono, semitono, tono, tono, tono, semitono</span>. Ejemplo resuelto, empezando en Do (cuerda 5, traste 3): Do +2 trastes = Re (5), +2 = Mi (7), +1 = Fa (8), +2 = Sol (10), +2 = La (12), +2 = Si (14), +1 = Do (15). Llegaste a Do otra vez, una octava más agudo.'},
 {key:'La receta (T T S T T T S) es la misma para las doce notas. Si te la sabes, puedes armar cualquier escala mayor sin memorizar nombres.'},
 {w:'scale'},
 E({id:'3a',t:'Do mayor en una sola cuerda',min:3,bpm:60,steps:['Empieza en la cuerda 5, traste 3 (Do).','Sube siguiendo la receta: trastes 3, 5, 7, 8, 10, 12, 14 y 15.','Di el número de cada nota mientras la tocas: 1, 2, 3… hasta 8.','Fíjate en los dos saltos cortos (un traste): entre el 3 y el 4, y entre el 7 y el 8.'],goal:'Tocas la escala de ida y vuelta diciendo los números sin equivocarte.',fig:pts([[5,3,'1','root'],[5,5,'2'],[5,7,'3'],[5,8,'4'],[5,10,'5'],[5,12,'6'],[5,14,'7'],[5,15,'8','root']],{to:15})}),
 {check:[['¿Cuántos trastes mide un tono?','Dos trastes. Un semitono es un traste.'],['Si empiezas en la cuerda 6, traste 5 (La), ¿qué trastes tocas para La mayor?','5, 7, 9, 10, 12, 14, 16 y 17: la misma receta T T S T T T S.'],['¿Entre qué números caen los dos semitonos?','Entre el 3 y el 4, y entre el 7 y el 8.']]},
 {step:'Paso 3',t:'Una forma que cabe en la mano',p:'Tocar la escala en una sola cuerda obliga a recorrer todo el mástil. Por eso se usa una <b>forma</b>: el mismo dibujo de puntos, repartido en tres cuerdas, que se toca sin mover la mano. La llamaremos <span class="hl">la forma de una octava</span>. Empieza siempre en la cuerda 6, y <b>la primera nota le da nombre a la escala</b>: si empiezas en el traste 3 (Sol), tocas Sol mayor.'},
 E({id:'3b',t:'La forma de una octava (Sol mayor)',min:4,bpm:60,steps:['Cuerda 6: trastes 3, 5 y 7 con los dedos 1, 3 y 4. Son los números 1, 2 y 3.','Cuerda 5: trastes 3, 5 y 7 con los dedos 1, 3 y 4. Son el 4, el 5 y el 6.','Cuerda 4: trastes 4 y 5 con los dedos 2 y 3. Son el 7 y el 8 (Sol otra vez).','Sube y baja una nota por pulso. Cuando salga limpio tres veces, sube 5 bpm.'],goal:'Tocas la forma de ida y vuelta a 80 bpm sin ver la mano.',fig:pts([[6,3,'1','root'],[6,5,'2'],[6,7,'3'],[5,3,'4'],[5,5,'5'],[5,7,'6'],[4,4,'7'],[4,5,'8','root']],{to:8})}),
 {step:'Paso 4',t:'Mover la forma cambia la tonalidad',p:'La forma no cambia; lo que cambia es dónde la empiezas. Recuerda las notas de la cuerda 6 de la lección 1: traste 1 = Fa, 3 = Sol, 5 = La, 8 = Do. Empieza la misma forma en el traste 5 y tocas La mayor; en el 8, Do mayor. Una sola forma te da las doce escalas mayores.'},
 E({id:'3c',t:'Mueve la forma',min:4,bpm:70,steps:['Toca la forma empezando en el traste 5: es La mayor (el diagrama la muestra).','Ahora empiézala en el traste 8: Do mayor.','Ahora en el traste 1: Fa mayor.','Antes de cada vuelta di en voz alta el nombre de la primera nota.'],goal:'Tocas la escala mayor en cuatro tonalidades con la misma forma.',fig:pts([[6,5,'1','root'],[6,7,'2'],[6,9,'3'],[5,5,'4'],[5,7,'5'],[5,9,'6'],[4,6,'7'],[4,7,'8','root']],{to:10})}),
 {step:'Paso 5',t:'Grados: tocar con números',p:'A cada nota de la escala le damos un número, su <b>grado</b>: la primera es el 1, la siguiente el 2, y así hasta el 7; el 8 es otra vez el 1, una octava arriba. Una <b>tonalidad</b> es la escala con su 1 como «casa»: la nota donde la música descansa. Si tocas con números en vez de con nombres, la misma melodía funciona en cualquier tonalidad: solo mueves la forma.'},
 E({id:'3d',t:'Toca por números',min:3,bpm:70,steps:['Pon la forma de una octava en el traste 3 (Sol mayor). Ubica los números: 1 = cuerda 6 traste 3, 3 = cuerda 6 traste 7, 5 = cuerda 5 traste 5, 8 = cuerda 4 traste 5.','Toca 1 – 3 – 5 – 8 y regresa 8 – 5 – 3 – 1 (el diagrama lo muestra).','Toca 1 – 2 – 3 – 1 y luego 5 – 4 – 3 – 2 – 1.','Mueve la forma al traste 5 (La mayor) y toca los mismos números.'],goal:'Los mismos números suenan igual en Sol y en La, solo más agudo.',fig:pts([[6,3,'1','root'],[6,7,'3'],[5,5,'5'],[4,5,'8','root'],[5,5,'5'],[6,7,'3'],[6,3,'1','root']],{to:8})}),
 E({id:'3e',t:'Una melodía en tres tonalidades',min:5,bpm:80,steps:['«Estrellita» en números: 1 1 5 5 6 6 5 · 4 4 3 3 2 2 1.','Tócala con la forma en el traste 3 (Sol mayor). El diagrama te la muestra.','Mueve la forma al traste 5 y tócala en La mayor.','Ahora en el traste 8: Do mayor. Los números no cambian.'],goal:'Tocas la melodía en tres tonalidades sin pensar en nombres de notas.',fig:pts([[6,3,'1','root'],[6,3,'1','root'],[5,5,'5'],[5,5,'5'],[5,7,'6'],[5,7,'6'],[5,5,'5'],[5,3,'4'],[5,3,'4'],[6,7,'3'],[6,7,'3'],[6,5,'2'],[6,5,'2'],[6,3,'1','root']],{to:8})}),
 {check:[['¿Qué le da nombre a la escala cuando usas la forma de una octava?','La primera nota, en la cuerda 6: traste 3 = Sol mayor, traste 5 = La mayor.'],['Quieres tocar Do mayor con la forma. ¿En qué traste empiezas?','En el traste 8 de la cuerda 6, que es Do.'],['¿Por qué conviene pensar en números y no en nombres?','Porque los números son iguales en todas las tonalidades: mueves la forma y la melodía sale sola.']]},
 {box:'Errores comunes',ul:['Contar mal los saltos: un tono son dos trastes, no uno.','Olvidar los dos semitonos (entre 3–4 y 7–8): la escala suena «rara».','Pensar que cada tonalidad tiene otra forma: es la misma forma movida.','Aprenderte nombres de notas sin los números: así no puedes transportar.']},
 {sec:'Transportar sin sufrir',p:'Si una canción está en Do y a tu voz le queda mejor en Re, mueve la forma dos trastes hacia arriba (un tono). Como los números no cambian, la melodía y los acordes se conservan.'},
 {trick:['Semitono = 1 traste · tono = 2 trastes.','Receta de la escala mayor: T T S T T T S.','La forma de una octava empieza en la cuerda 6; esa nota le da nombre a la escala.','Cuerda 6: traste 1 Fa, 3 Sol, 5 La, 8 Do.','Para cambiar de tonalidad, mueve la forma y conserva los números.']}]},
{id:4,part:2,title:'Los modos, sin misticismo',sub:'Mismas notas, otra casa',
 lead:'Un modo es la escala mayor vista desde otra de sus notas: las mismas siete notas, pero con otro centro y otro color.',
 blocks:[
 {aim:['Entender qué es el centro (la «casa») de una escala.','Saber que los siete modos salen de la escala mayor empezando en cada grado.','Conocer la fórmula y la nota característica de cada modo.','Encontrar la escala madre de cualquier modo.','Tocar un modo sobre un acorde para que suene a ese modo.']},
 {step:'Paso 1',t:'El centro: la nota donde la música descansa',p:'En toda canción hay una nota que se siente como <b>casa</b>: cuando la melodía llega ahí, suena terminada. Se llama <b>tónica</b> o centro. En la escala de Do mayor la casa es Do. Pero las siete notas de Do mayor (Do Re Mi Fa Sol La Si) pueden tener otra casa: si la música gira alrededor de Re y termina en Re, esas mismas notas suenan distintas. Eso es un <b>modo</b>: no cambias de notas, <span class="hl">cambias de casa</span>.'},
 {step:'Paso 2',t:'Los siete modos son siete puntos de partida',p:'Toca Do mayor empezando y terminando en cada una de sus notas y obtienes los siete modos: desde Do, <b>jónico</b> (la escala mayor de siempre); desde Re, <b>dórico</b>; desde Mi, <b>frigio</b>; desde Fa, <b>lidio</b>; desde Sol, <b>mixolidio</b>; desde La, <b>eólico</b> (la escala menor natural); desde Si, <b>locrio</b>. Los nombres vienen de regiones de la antigua Grecia; no hace falta saber por qué, solo el orden: <span class="hl">jónico, dórico, frigio, lidio, mixolidio, eólico, locrio</span>.'},
 {w:'mode'},
 E({id:'4a',t:'Mapa de modos en Do',min:4,bpm:60,steps:['Toca la escala de Do mayor del diagrama (cuerdas 5, 4 y 3) usando el paso a paso (›) para ver cada nota y su dedo.','Ahora tócala siete veces, empezando cada vez en una nota distinta: Do, Re, Mi, Fa, Sol, La y Si, y sube ocho notas.','Antes de cada vuelta di el nombre del modo: jónico, dórico, frigio, lidio, mixolidio, eólico, locrio.','Termina siempre en la nota donde empezaste y quédate un momento en ella.'],goal:'Nombras los siete modos en orden sin mirar.',fig:pts([[5,3,'Do','root'],[5,5,'Re'],[4,2,'Mi'],[4,3,'Fa'],[4,5,'Sol'],[3,2,'La'],[3,4,'Si'],[3,5,'Do','root']],{to:6})}),
 {step:'Paso 3',t:'La fórmula de cada modo',p:'Para sentir el color de un modo conviene compararlo con la escala mayor desde la misma nota. Usando grados (lección 3), con ♭ = un semitono abajo y ♯ = un semitono arriba: <b>Jónico</b> 1 2 3 4 5 6 7 · <b>Lidio</b> 1 2 3 ♯4 5 6 7 · <b>Mixolidio</b> 1 2 3 4 5 6 ♭7 · <b>Dórico</b> 1 2 ♭3 4 5 6 ♭7 · <b>Eólico</b> 1 2 ♭3 4 5 ♭6 ♭7 · <b>Frigio</b> 1 ♭2 ♭3 4 5 ♭6 ♭7 · <b>Locrio</b> 1 ♭2 ♭3 4 ♭5 ♭6 ♭7. Están ordenados del más brillante al más oscuro: cada uno baja una nota más. Los que tienen 3 (tercera mayor) suenan alegres; los que tienen ♭3, menores.'},
 {key:'Cada modo tiene una <b>nota característica</b>, la que lo distingue de la escala mayor o menor más parecida: dórico = <b>6</b> (un menor con sexta mayor), frigio = <b>♭2</b>, lidio = <b>♯4</b>, mixolidio = <b>♭7</b>, eólico = <b>♭6</b>, locrio = <b>♭5</b>. Al improvisar en un modo, esa es la nota que hay que hacer sonar para que se note.'},
 {step:'Paso 4',t:'Ejemplo resuelto: Re dórico',p:'Re dórico usa las notas de Do mayor desde Re: <b>Re Mi Fa Sol La Si Do Re</b>. Compáralo con Re menor natural (eólico): Re Mi Fa Sol La <b>Si♭</b> Do Re. Solo cambia una nota: dórico tiene <b>Si natural</b>, la sexta mayor. Por eso suena menor pero menos triste, más cálido: es el sonido de «Oye cómo va» de Santana. Para tocarlo necesitas que la música gire alrededor de Re: un acorde de Re menor de fondo hace ese trabajo.'},
 {step:'Paso 5',t:'Encontrar la escala madre',p:'Si alguien te pide «La dórico», ¿qué notas usas? Busca la escala mayor de la que sale (la <b>escala madre</b>). Como dórico empieza en el 2º grado, la madre está <b>un tono abajo</b>: La dórico = notas de <b>Sol mayor</b> (Sol La Si Do Re Mi Fa♯), empezando en La. Las demás reglas: frigio, la madre está 4 semitonos abajo (Mi frigio = Do mayor); lidio, 5 semitonos abajo (Fa lidio = Do mayor); mixolidio, 5 semitonos arriba (Sol mixolidio = Do mayor); eólico, 3 semitonos arriba (La eólico = Do mayor). En la guitarra: mueve la forma de la escala mayor que ya conoces y cambia la nota donde descansas.'},
 {check:[['¿Qué tienen en común Do jónico y Re dórico?','Las mismas siete notas; solo cambia la casa (Do o Re).'],['¿Cuál es la nota característica del mixolidio?','La ♭7: es la escala mayor con la séptima un semitono abajo.'],['¿Qué notas usa La dórico?','Las de Sol mayor (Sol La Si Do Re Mi Fa♯), con La como casa.'],['¿Por qué un modo necesita un acorde de fondo?','Porque sin algo que fije la casa, el oído escucha las notas como la escala mayor madre.']]},
 {step:'Paso 6',t:'Tocar un modo de verdad: sobre su acorde',p:'Los modos se sienten cuando hay un acorde o un bajo que marca la casa. Por eso los ejercicios usan una pista que se queda en el acorde del modo. Tres sabores para empezar, los más usados en música popular: <b>dórico</b> (menor cálido: funk, Santana), <b>mixolidio</b> (mayor con sabor a rock: «Sweet Home Alabama», mucho rock clásico) y <b>lidio</b> (mayor flotante, de sueño: el tema de Los Simpson, música de películas). En cada uno, empieza y termina tus frases en la casa y busca la nota característica.'},
 E({id:'4b',t:'Re dórico sobre su acorde',min:4,steps:['Inicia la pista: alterna Re menor y Sol mayor.','Toca solo notas de Do mayor, pero empieza y termina tus frases en Re.','Busca el Si (la sexta): suena justo cuando entra el acorde de Sol. Es la nota que hace dórico al modo.','Compara: cambia el Si por Si♭ y escucha cómo se vuelve más triste (eólico).'],goal:'Tus frases suenan menores, pero cálidas, y terminan en Re.',track:{k:2,p:'dorico',st:'balada',bpm:72}}),
 E({id:'4c',t:'Sol mixolidio con sabor a rock',min:4,steps:['Inicia la pista: Sol – Fa – Do – Sol.','Toca la escala de Sol mayor, pero cambia el Fa♯ por Fa natural (la ♭7).','Busca el Fa justo cuando suena el acorde de Fa y escucha cómo encaja.','Termina tus frases en Sol.'],goal:'Escuchas la diferencia entre Fa♯ (mayor) y Fa (mixolidio).',track:{k:1,p:'mixo',st:'rock',bpm:96}}),
 E({id:'4d',t:'Fa lidio flotante',min:3,steps:['Inicia la pista: Fa mayor y Sol mayor.','Toca las notas de Do mayor centradas en Fa.','Detente en Si (la cuarta aumentada, ♯4) sobre el acorde de Fa y escucha ese color brillante, como de sueño.','Termina en Fa.'],goal:'Reconoces el sonido brillante del lidio.',track:{k:11,p:'lidio',st:'balada',bpm:70}}),
 {box:'Qué modo va sobre qué acorde (en una tonalidad mayor)',ul:['Acorde I → jónico · ii → dórico · iii → frigio','IV → lidio · V → mixolidio','vi → eólico · vii° → locrio (casi no se usa como casa)']},
 {box:'Errores comunes',ul:['Creer que cada modo exige notas nuevas: son las de la escala madre.','Tocar el modo sin un acorde que fije la casa: sonará como la escala mayor.','Memorizar siete formas por tonalidad: aprende la escala mayor y mueve la casa.','Olvidar la nota característica: sin ella el modo no se distingue.','Usar el locrio como centro estable: su quinta disminuida lo hace inestable.']},
 {trick:['Modo = escala mayor desde otro grado: 1 jónico, 2 dórico, 3 frigio, 4 lidio, 5 mixolidio, 6 eólico, 7 locrio.','De brillante a oscuro: lidio, jónico, mixolidio, dórico, eólico, frigio, locrio.','Dórico = menor con 6 mayor · mixolidio = mayor con ♭7 · lidio = mayor con ♯4.','Escala madre de un dórico: un tono abajo (La dórico = Sol mayor).','No cambias de notas: cambias de casa.']}]},
{id:5,part:2,title:'Acordes: de dónde salen realmente',sub:'Terceras apiladas y escala armonizada',
 lead:'Un acorde es una pila de terceras sacada de la escala. Si entiendes cómo se arma, puedes construir cualquiera y saber cuáles combinan.',
 blocks:[
 {aim:['Saber qué es una tríada: raíz, tercera y quinta.','Armar un acorde saltando notas de la escala.','Distinguir mayor, menor, disminuido y aumentado por sus distancias.','Entender por qué un acorde de guitarra usa 5 o 6 cuerdas si solo tiene 3 notas.','Saber qué acordes nacen de cada tonalidad mayor (la escala armonizada).']},
 {step:'Paso 1',t:'Una tríada: tres notas a saltos',p:'Un <b>acorde</b> son tres o más notas sonando juntas. El más básico es la <b>tríada</b>: tres notas. Se arma con la escala: toma una nota, <b>salta una</b>, toma la siguiente, salta otra y toma la siguiente. Ejemplo resuelto en Do mayor (Do Re Mi Fa Sol La Si): empieza en <b>Do</b>, salta Re, toma <b>Mi</b>, salta Fa, toma <b>Sol</b>. Do–Mi–Sol es el acorde de Do. A la primera nota se le llama <b>raíz</b> (le da nombre), a la segunda <b>tercera</b> y a la tercera <b>quinta</b>, por la distancia que tienen con la raíz.'},
 {step:'Paso 2',t:'Mayor o menor: lo decide la tercera',p:'Mide las distancias en semitonos (lección 2). En Do–Mi–Sol: Do→Mi son 4 semitonos (<b>tercera mayor</b>) y Mi→Sol son 3. Eso es un <b>acorde mayor</b>: suena alegre. Ahora arma desde Re con la misma regla: <b>Re–Fa–La</b>. Re→Fa son 3 semitonos (<b>tercera menor</b>) y Fa→La son 4. Eso es un <b>acorde menor</b>: suena triste. La quinta (7 semitonos desde la raíz) es igual en los dos. Hay dos tipos más: el <b>disminuido</b> (3 + 3 semitonos: tercera menor y quinta un semitono más baja) suena tenso, y el <b>aumentado</b> (4 + 4) suena a suspenso.'},
 {key:'La diferencia entre un acorde mayor y uno menor es <b>una sola nota</b>: la tercera. Bájala un semitono (un traste) y el acorde mayor se vuelve menor. En las fórmulas: mayor = 1 3 5 · menor = 1 ♭3 5 · disminuido = 1 ♭3 ♭5 · aumentado = 1 3 ♯5.'},
 {w:'chord',types:['maj','min','dim','aug']},
 E({id:'5a',t:'Tríadas en tres cuerdas',min:4,bpm:60,steps:['Do mayor en las cuerdas 3, 2 y 1: traste 5 (Do, la raíz), traste 5 (Mi, la tercera) y traste 3 (Sol, la quinta). Usa el paso a paso (›) para ver qué dedo va en cada una.','Baja un traste la nota de la cuerda 2 (Mi → Mi♭): ahora es Do menor. Solo cambió la tercera.','Mueve la forma al traste 7 (Re mayor y Re menor) y al traste 2 (La mayor y La menor).','Alterna mayor y menor, cuatro pulsos cada uno, y escucha el cambio de alegre a triste.'],goal:'Conviertes cualquier tríada mayor en menor sin pensarlo.',fig:pts([[3,5,'1','root'],[2,5,'3'],[1,3,'5']],{to:7})}),
 {step:'Paso 3',t:'¿Por qué el acorde usa 5 o 6 cuerdas?',p:'Si una tríada son tres notas, ¿por qué el Do abierto (x32010) usa cinco cuerdas? Porque <b>repite notas en otra octava</b>. Míralo cuerda por cuerda: cuerda 5, traste 3 = <b>Do</b>; cuerda 4, traste 2 = <b>Mi</b>; cuerda 3 al aire = <b>Sol</b>; cuerda 2, traste 1 = <b>Do</b> otra vez; cuerda 1 al aire = <b>Mi</b> otra vez. Solo hay tres notas distintas (Do, Mi, Sol); las repeticiones hacen que suene más lleno. Por eso la «x» de la cuerda 6 importa: si la tocas, sonaría un Mi en el bajo y el acorde ya no tendría a Do como nota más grave.'},
 E({id:'5b',t:'Encuentra la tercera',min:3,steps:['Toca Mi mayor y busca su tercera (Sol♯): es la cuerda 3, traste 1. Usa el paso a paso (›) para ver cada acorde y sus dedos.','Quita ese dedo: la cuerda 3 suena al aire (Sol) y el acorde se vuelve Mi menor.','En La mayor, la tercera (Do♯) está en la cuerda 2, traste 2: bájala al traste 1 y tienes La menor.','En Re mayor, la tercera (Fa♯) está en la cuerda 1, traste 2: bájala al traste 1 y tienes Re menor.'],goal:'Señalas la tercera de los tres acordes.',fig:chords(ch('E','Em','A','Am','D','Dm'))}),
 {check:[['¿Qué notas forman el acorde de Sol mayor?','Sol, Si y Re (salta La y Do en la escala de Sol).'],['Re–Fa–La, ¿es mayor o menor? ¿Por qué?','Menor: de Re a Fa hay 3 semitonos (tercera menor).'],['¿Qué nota cambia entre Mi mayor y Mi menor?','La tercera: Sol♯ en mayor, Sol en menor.']]},
 {step:'Paso 4',t:'La escala armonizada: los acordes de una tonalidad',p:'Arma una tríada sobre <b>cada</b> nota de la escala mayor, usando solo notas de esa escala. En Do mayor: Do–Mi–Sol = <b>Do</b>; Re–Fa–La = <b>Rem</b>; Mi–Sol–Si = <b>Mim</b>; Fa–La–Do = <b>Fa</b>; Sol–Si–Re = <b>Sol</b>; La–Do–Mi = <b>Lam</b>; Si–Re–Fa = <b>Si°</b> (disminuido). El patrón es siempre el mismo en cualquier tonalidad mayor: <span class="hl">mayor, menor, menor, mayor, mayor, menor, disminuido</span>. Se escribe con números romanos: mayúsculas para mayores y minúsculas para menores: <b>I ii iii IV V vi vii°</b>. Por eso los acordes de una canción combinan: todos salen de la misma escala.'},
 {w:'harm'},
 {step:'Paso 5',t:'Ejemplo resuelto: los acordes de Sol mayor',p:'La escala de Sol mayor es Sol La Si Do Re Mi Fa♯. Aplica el patrón: I = <b>Sol</b>, ii = <b>Lam</b>, iii = <b>Sim</b>, IV = <b>Do</b>, V = <b>Re</b>, vi = <b>Mim</b>, vii° = <b>Fa♯°</b>. Si una canción está en Sol, lo más probable es que use Sol, Do, Re y Mim, que son de los acordes más fáciles en la guitarra. Sobre cifrado: en partituras en inglés verás C = Do, Dm = Re menor, B° o Bdim = Si disminuido, C+ o Caug = Do aumentado.'},
 E({id:'5c',t:'La escala armonizada',min:5,bpm:70,steps:['Toca en orden: Do, Rem, Mim, Fa, Sol, Lam y Si° (x2343x). Con el paso a paso (›) ves cada acorde, sus dedos y la cejilla de Fa.','Cuatro golpes por acorde.','Di el grado en voz alta mientras tocas: uno, dos menor, tres menor, cuatro, cinco, seis menor, siete disminuido.','Repite en Sol mayor: Sol, Lam, Sim, Do, Re, Mim, Fa♯°, usando la tabla de arriba.'],goal:'Tocas los siete acordes de dos tonalidades nombrando los grados.',fig:chords(ch('C','Dm','Em','F','G','Am','Bdim'))}),
 E({id:'5d',t:'Arpegios 1–3–5',min:3,bpm:60,steps:['Arpegio de Do: Do (5/3), Mi (4/2), Sol (3/0), Do (2/1), Mi (1/0). Es el acorde de Do tocado nota por nota.','Toca una nota por pulso, de ida y vuelta, dejando sonar cada una.','Haz lo mismo con La menor (x02210): La, Mi, La, Do, Mi.','Escucha que el arpegio y el acorde suenan «igual», solo que separados.'],goal:'Escuchas cada nota del acorde por separado.',fig:pts([[5,3,'1','root'],[4,2,'3'],[3,0,'5'],[2,1,'1','root'],[1,0,'3']],{to:5})}),
 {check:[['¿Qué tipo de acorde hay en el grado vi de una tonalidad mayor?','Menor (en Do mayor, La menor).'],['¿Cuáles son los acordes mayores de Re mayor?','Re (I), Sol (IV) y La (V).'],['¿Por qué el grado vii es disminuido?','Porque sus notas (en Do: Si–Re–Fa) forman tercera menor y quinta disminuida.']]},
 {sec:'Inversiones',p:'El mismo acorde puede tener la tercera o la quinta como nota más grave: se llama <b>inversión</b>. Las notas son las mismas; cambia cuál suena abajo. Se escriben con barra: Do/Mi es Do con Mi en el bajo. En guitarra aparecen solas al tocar un acorde en distintas zonas del mástil (lección 7) y sirven para que el bajo camine suave entre acordes.'},
 {box:'Errores comunes',ul:['Creer que mayor y menor se distinguen por la raíz: se distinguen por la tercera.','Olvidar que el acorde del grado vii es disminuido.','Memorizar acordes por tonalidad en vez de armarlos con la regla.','Tocar las cuerdas marcadas con x: cambian el bajo del acorde.','Omitir la tercera: es la nota que define el carácter.']},
 {trick:['Acorde = raíz, salta una, tercera, salta una, quinta.','Mayor 1–3–5 · menor 1–♭3–5 · disminuido 1–♭3–♭5 · aumentado 1–3–♯5.','Mayor a menor: baja la tercera un traste.','Escala mayor: I ii iii IV V vi vii° (mayor, menor, menor, mayor, mayor, menor, disminuido).','Los tres acordes mayores de una tonalidad: I, IV y V.']}]},
{id:6,part:2,title:'Séptimas, tensiones y color',sub:'Cuatro notas y más',
 lead:'Añade una nota a la tríada y el acorde cambia de color: más suave, más tenso o más jazzero, sin dejar de cumplir su función.',
 blocks:[
 {aim:['Armar acordes de séptima agregando otra tercera a la tríada.','Distinguir maj7, 7 (dominante), m7 y m7♭5 por su sonido y su fórmula.','Entender por qué el acorde 7 «pide» ir a otro acorde.','Saber qué acordes con séptima nacen de una tonalidad.','Usar tensiones (9, 11, 13) y acordes sus y add con intención.']},
 {step:'Paso 1',t:'Una tercera más: la séptima',p:'En la lección 5 armamos tríadas saltando notas de la escala: raíz, tercera, quinta. Si sigues un salto más, llegas a la <b>séptima</b>. Ejemplo en Do mayor: Do, (Re), Mi, (Fa), Sol, (La), <b>Si</b>. Do–Mi–Sol–Si es <b>Do maj7</b> (Do con séptima mayor). La séptima está a 11 semitonos de la raíz si es <b>mayor</b> y a 10 si es <b>menor</b>, y esa diferencia de un traste cambia todo el carácter.'},
 {step:'Paso 2',t:'Los cuatro acordes de séptima que más usarás',p:'<b>maj7</b> = 1 3 5 7: tríada mayor con séptima mayor. Suena suave, nostálgico, de bossa nova o balada. <b>7</b> (se lee «séptima» o «dominante») = 1 3 5 ♭7: tríada mayor con séptima menor. Suena tenso y con fuerza, de blues y rock and roll. <b>m7</b> = 1 ♭3 5 ♭7: tríada menor con séptima menor. Suena cálido y relajado. <b>m7♭5</b> (o «semidisminuido», ø) = 1 ♭3 ♭5 ♭7: suena inestable y misterioso. Cuidado con el nombre: «Do7» <b>no</b> es «Do maj7». Si dice solo 7, la séptima es menor.'},
 {step:'Paso 3',t:'Ejemplo resuelto: de Do a Do maj7 y a Do7 con un dedo',p:'Toca Do (x32010). La nota más aguda de la cuerda 2 es Do (traste 1). Ahora <b>levanta ese dedo</b>: la cuerda 2 al aire suena Si, la séptima mayor. Eso es <b>Do maj7 (x32000)</b>. Ahora vuelve a Do y agrega el meñique en la cuerda 3, traste 3: esa nota es Si♭, la séptima menor. Eso es <b>Do7 (x32310)</b>. Con un solo dedo pasas por los tres colores. En La menor (x02210) levanta el dedo de la cuerda 3: suena Sol al aire, la séptima menor, y tienes <b>La m7 (x02010)</b>.'},
 {w:'chord',types:['maj7','dom7','m7','m7b5','sus2','sus4','add9','dom9'],init:{k:0,t:'dom7'}},
 E({id:'6a',t:'De tríada a séptima',min:4,bpm:60,steps:['Toca Do (x32010), luego Do maj7 (x32000), luego Do7 (x32310). Cuatro golpes cada uno. Con el paso a paso (›) ves los dedos de cada uno.','Escucha qué nota cambia arriba: Do, luego Si, luego Si♭.','Toca La menor (x02210) y La m7 (x02010): solo levantas un dedo.','Describe con una palabra cada color: «normal», «suave», «tenso», «cálido».'],goal:'Describes con tus palabras el color de cada acorde.',fig:chords(ch('C','Cmaj7','C7','Am','Am7'))}),
 {key:'El acorde <b>7 (dominante)</b> tiene entre su tercera y su séptima un <b>tritono</b> (6 semitonos), la distancia más tensa. En Sol7 son Si y Fa. Esa tensión se resuelve cuando Si sube a Do y Fa baja a Mi: es decir, cuando llegas al acorde de Do. Por eso el acorde del grado V (Sol7 en Do) «empuja» hacia el I. Es el motor de casi toda la música occidental.'},
 {step:'Paso 4',t:'Las séptimas de una tonalidad',p:'Igual que con las tríadas, puedes armar un acorde de cuatro notas sobre cada grado de la escala mayor. En Do mayor salen: <b>Do maj7, Rem7, Mim7, Fa maj7, Sol7, Lam7 y Si m7♭5</b>. El patrón para cualquier tonalidad mayor es: <span class="hl">Imaj7, ii m7, iii m7, IVmaj7, V7, vi m7, vii m7♭5</span>. Fíjate que hay <b>un solo dominante</b>: el del grado V. Si en una canción ves un acorde 7, casi siempre está a punto de ir a otro acorde una quinta abajo.'},
 {w:'harm',init:{k:0,sev:1}},
 E({id:'6b',t:'ii – V – I con séptimas',min:4,steps:['Inicia la pista: Rem7 – Sol7 – Do maj7, la cadencia más famosa del jazz.','Rasguea junto a la pista: Rem7 (xx0211), Sol7 (320001), Do maj7 (x32000).','Escucha la séptima de cada acorde bajar un semitono al siguiente: el Do de Rem7 baja a Si en Sol7, y el Fa de Sol7 baja a Mi en Do maj7.','Cuando lo tengas, tararea esas notas que bajan mientras tocas.'],goal:'Cambias de acorde a tiempo durante cuatro vueltas.',track:{k:0,p:'iivi',st:'balada',bpm:70}}),
 E({id:'6d',t:'Las séptimas de la escala',min:5,bpm:70,steps:['Toca en orden: Do maj7, Rem7, Mim7, Fa maj7, Sol7, Lam7 y Si m7♭5 (x2323x). Usa el paso a paso (›) para ver los dedos de cada uno.','Cuatro golpes por acorde.','Di el grado mientras tocas: uno maj7, dos m7, tres m7, cuatro maj7, cinco 7, seis m7, siete m7♭5.','Señala cuál es el único dominante (Sol7) y escucha cómo empuja hacia Lam7 o hacia Do.'],goal:'Tocas los siete acordes con séptima sin detenerte.',fig:chords(ch('Cmaj7','Dm7','Em7','Fmaj7','G7','Am7','Bm7b5'))}),
 {check:[['¿Qué diferencia hay entre Do7 y Do maj7?','La séptima: Do7 lleva Si♭ (séptima menor), Do maj7 lleva Si (séptima mayor).'],['¿Qué acorde con séptima hay en el grado V de Sol mayor?','Re7 (dominante).'],['¿Por qué Sol7 quiere ir a Do?','Porque el tritono entre Si y Fa se resuelve en Do y Mi, notas del acorde de Do.']]},
 {step:'Paso 5',t:'Tensiones: 9, 11 y 13',p:'Si sigues apilando terceras después de la séptima llegas a la <b>9</b>, la <b>11</b> y la <b>13</b>. Son las notas 2, 4 y 6 de la escala, pero una octava arriba. Agregan color sin cambiar la función del acorde: un Sol9 sigue siendo un dominante que va a Do, solo que con un sonido más rico (funk, soul). En la guitarra casi nunca se tocan todas las notas: se quita la quinta o la raíz (la toca el bajo) para que quepan en los dedos.'},
 {step:'Paso 6',t:'sus y add: quitar o agregar sin cambiar la casa',p:'Un acorde <b>sus</b> (suspendido) <b>quita la tercera</b> y pone en su lugar la 2ª (sus2) o la 4ª (sus4). Sin tercera no es mayor ni menor: queda «en el aire» y pide volver al acorde normal. Ejemplo: Re sus4 (xx0233) tiene Sol (la 4ª) en la cuerda 1 en lugar de Fa♯ (la 3ª); al regresar al traste 2 de la cuerda 1 (xx0232) vuelve a ser Re y la tensión se resuelve. En cambio un acorde <b>add9</b> <b>conserva</b> la tercera y le agrega la 9: suena abierto y moderno, pero sigue siendo mayor.'},
 E({id:'6c',t:'Acordes sus que resuelven',min:3,bpm:70,steps:['Re sus4 (xx0233) dos pulsos y Re (xx0232) dos pulsos: solo cambia la cuerda 1, del traste 3 (Sol, con el meñique) al traste 2 (Fa♯).','La sus2 (x02200) y La (x02220): solo cambia la cuerda 2 (al aire o traste 2).','Combina: Re sus4 – Re – La sus2 – La. Este movimiento se usa muchísimo en el pop y el rock.','Fíjate cómo el sus «pide» volver al acorde normal.'],goal:'Sientes que el sus pide volver al acorde normal.',fig:chords(ch('Dsus4','D','Asus2','A'),2)}),
 {sec:'La séptima baja, la tercera recibe',p:'En ii–V–I, la séptima de cada acorde baja un semitono hasta la tercera del siguiente: Do (7ª de Rem7) baja a Si (3ª de Sol7) y Fa (7ª de Sol7) baja a Mi (3ª de Do maj7). Por eso esta cadencia suena tan natural: las voces se mueven lo mínimo.'},
 {box:'Errores comunes',ul:['Confundir «7» con «maj7»: si dice solo 7, la séptima es menor.','Poner séptima mayor en un dominante: el dominante lleva ♭7.','Creer que m7♭5 es raro: es el acorde del grado vii.','Cargar tensiones en todos los acordes: úsalas con intención.','Confundir sus con add: sus quita la tercera, add la conserva.']},
 {trick:['maj7: suave · 7: tenso · m7: cálido · m7♭5: inestable.','maj7 = 1 3 5 7 · 7 = 1 3 5 ♭7 · m7 = 1 ♭3 5 ♭7 · m7♭5 = 1 ♭3 ♭5 ♭7.','Escala mayor con séptimas: Imaj7 ii m7 iii m7 IVmaj7 V7 vi m7 vii m7♭5.','9 = 2 · 11 = 4 · 13 = 6 (una octava arriba).','sus quita la 3ª · add la conserva y agrega.']}]},
{id:7,part:3,title:'CAGED: el mástil completo sobre una idea',sub:'Cinco formas que cubren todo el cuello',
 lead:'Los acordes abiertos que ya conoces (Do, La, Sol, Mi y Re) son cinco formas que puedes mover a cualquier traste. Juntas cubren todo el mástil.',
 blocks:[
 {aim:['Entender por qué un acorde abierto se puede mover con cejilla.','Saber dónde está la raíz en cada una de las cinco formas.','Tocar el mismo acorde en cinco lugares del mástil.','Armar cualquier acorde partiendo de su raíz en las cuerdas 6, 5 o 4.','Usar una sola zona del mástil para acordes y escalas.']},
 {step:'Paso 1',t:'La cejilla es una cejuela que se mueve',p:'Las cuerdas al aire suenan porque la <b>cejuela</b> (la pieza blanca al inicio del mástil) las detiene. Cuando haces una <b>cejilla</b> con el dedo 1, tu dedo hace el trabajo de la cejuela en otro traste. Por eso cualquier acorde abierto se puede mover: tocas la misma forma con los otros dedos y pones la cejilla donde antes estaba la cejuela. Ejemplo: Mi mayor (022100) movido un traste, con cejilla en el 1, es <b>Fa</b> (133211); movido tres trastes es <b>Sol</b> (355433). La forma no cambia; el traste de la cejilla dice qué acorde es.'},
 {step:'Paso 2',t:'Las cinco formas y su raíz',p:'Los cinco acordes abiertos que se pueden mover son <b>C, A, G, E y D</b> (Do, La, Sol, Mi y Re): de ahí el nombre CAGED. Lo más importante de cada forma es saber <b>dónde está su raíz</b>, porque la raíz dice cómo se llama el acorde: <span class="hl">forma de E → raíz en la cuerda 6 · forma de A → cuerda 5 · forma de C → cuerda 5 · forma de G → cuerda 6 · forma de D → cuerda 4</span>. Si sabes las notas de las cuerdas 6, 5 y 4 (lección 1), sabes dónde poner cada forma.'},
 {key:'Las cinco formas <b>siempre aparecen en el mismo orden</b> a lo largo del mástil: C → A → G → E → D, y vuelve a empezar. Cada forma comparte notas con la siguiente, así que encajan como piezas de rompecabezas. Si conoces una, la siguiente está justo arriba.'},
 {w:'caged'},
 {step:'Paso 3',t:'Ejemplo resuelto: Do en cinco lugares',p:'Sigamos el orden desde la forma abierta. <b>Forma de C</b>: el Do abierto (x32010), raíz en la cuerda 5, traste 3. <b>Forma de A</b>: cejilla en el traste 3 (x35553); la raíz sigue en la cuerda 5, traste 3. <b>Forma de G</b>: alrededor del traste 5 (8–7–5–5–5–8); raíz en la cuerda 6, traste 8. <b>Forma de E</b>: cejilla en el traste 8 (8–10–10–9–8–8), raíz en la cuerda 6, traste 8. <b>Forma de D</b>: alrededor del traste 10 (xx–10–12–13–12), raíz en la cuerda 4, traste 10. Después de la forma de D vuelve la de C, una octava arriba (traste 12).'},
 E({id:'7a',t:'Las cinco formas de Do',min:5,bpm:60,steps:['Recorre las cinco formas con el paso a paso (›): cada una muestra su cejilla y qué dedo va en cada cuerda.','Abierta: forma de C (x32010). Traste 3: forma de A (x35553).','Traste 5: forma de G (8–7–5–5–5–8). Es la más difícil: si te cuesta, toca solo las cuerdas 4, 3 y 2 con una cejilla corta.','Traste 8: forma de E (8–10–10–9–8–8). Traste 10: forma de D (xx–10–12–13–12).','Cuatro golpes por forma, y antes de cada una di en qué cuerda está la raíz.'],goal:'Recorres las cinco formas de Do sin mirar el diagrama.',fig:chords([['C · forma C',[null,3,2,0,1,0]],['C · forma A',[null,3,5,5,5,3]],['C · forma G',[8,7,5,5,5,8]],['C · forma E',[8,10,10,9,8,8]],['C · forma D',[null,null,10,12,13,12]]])}),
 {check:[['¿En qué cuerda está la raíz de la forma de A?','En la cuerda 5.'],['Quieres Sol con la forma de E. ¿En qué traste pones la cejilla?','En el traste 3, porque Sol está en la cuerda 6, traste 3.'],['¿Qué forma sigue después de la de G?','La de E (el orden es C, A, G, E, D).']]},
 {step:'Paso 4',t:'Armar cualquier acorde desde la raíz',p:'Para tocar un acorde en otra zona no memorices posiciones: <b>busca la raíz</b> y arma la forma alrededor. Ejemplo resuelto con Re: su raíz está en la cuerda 6, traste 10 → forma de E con cejilla en el 10. En la cuerda 5, traste 5 → forma de A con cejilla en el 5 (x57775) o forma de C (x54232). En la cuerda 4 al aire → forma de D (el Re abierto de siempre). Para un acorde menor, usa la versión menor de la forma: Em, Am o Dm movidos con cejilla.'},
 E({id:'7b',t:'La raíz primero',min:3,steps:['Para Re, encuentra sus raíces: cuerda 6, traste 10; cuerda 5, traste 5; cuerda 4, al aire o traste 12.','Arma alrededor de cada raíz la forma que le corresponde: E (cuerda 6), A o C (cuerda 5), D (cuerda 4).','Repite con Sol: raíces en la cuerda 6, traste 3; cuerda 5, traste 10; cuerda 4, traste 5.','Toca cada forma y verifica que suena el mismo acorde, más grave o más agudo.'],goal:'Construyes tres formas de un acorde partiendo de la raíz.'}),
 {step:'Paso 5',t:'Tocar una canción sin saltar por el mástil',p:'Con CAGED puedes tocar los acordes de una canción cerca unos de otros. En Sol mayor, los acordes I, IV y V son Sol, Do y Re. Tócalos así: Sol con forma de E en el traste 3, Do con forma de A en el traste 3, Re con forma de A en el traste 5. La mano casi no se mueve: dos trastes como mucho. Así suenan las canciones de rock y pop con cejillas, y así se cambia de tonalidad: mueve todo el grupo de formas al mismo tiempo.'},
 E({id:'7c',t:'I – IV – V en una sola zona',min:4,bpm:80,steps:['En Sol: Sol (forma E, traste 3), Do (forma A, traste 3) y Re (forma A, traste 5). Usa el paso a paso (›) para ver las cejillas y los dedos.','Cuatro golpes cada uno, sin mover la mano más de dos trastes.','Repite en La: todo dos trastes más arriba (traste 5 y 7).','Cuando salga, cambia de acorde cada dos golpes.'],goal:'Cambias de acorde sin saltar por el mástil.',fig:chords([['G · forma E',[3,5,5,4,3,3]],['C · forma A',[null,3,5,5,5,3]],['D · forma A',[null,5,7,7,7,5]],['G · forma E',[3,5,5,4,3,3]]])}),
 {step:'Paso 6',t:'Cada forma tiene su escala',p:'Lo mejor de CAGED es que la zona de cada acorde también sirve para escalas y arpegios: las notas del acorde están dentro de la escala de esa zona. Ejemplo: La con forma de E en el traste 5 cae justo encima de la «caja 1» de la pentatónica de La menor (lección 10). Si sabes qué forma de acorde estás tocando, sabes qué escala y qué notas fuertes tienes bajo los dedos para improvisar.'},
 E({id:'7d',t:'Escala dentro del acorde',min:4,bpm:60,steps:['Toca La con la forma de E en el traste 5 (cejilla en el 5).','Sin mover la mano, toca la pentatónica de La menor, caja 1, con el paso a paso (›) para ver cada nota y su dedo.','Observa que las raíces (en rojo) de la escala son las mismas notas La del acorde.','Alterna: un compás de acorde y un compás de escala.'],goal:'Pasas del acorde a la escala sin cambiar de zona.',fig:boxFig(3,'min',1,10)}),
 {check:[['¿Qué hace la cejilla en una forma móvil?','El trabajo de la cejuela: detiene todas las cuerdas en ese traste.'],['Re con forma de A: ¿dónde va la cejilla?','En el traste 5, porque Re está en la cuerda 5, traste 5.'],['¿Por qué conviene tocar I, IV y V en la misma zona?','Porque cambias de acorde casi sin mover la mano.']]},
 {box:'Errores comunes',ul:['Tocar la forma sin identificar la raíz: pierdes el nombre del acorde.','Apretar la cejilla con fuerza en lugar de bien colocada: el dedo va justo detrás del traste, ligeramente de lado.','Aprender CAGED solo como acordes, sin relacionarlo con escalas.','Pensar que hay una forma mejor: todas son válidas; elige la más cercana.','Saltarte el orden: las formas siempre se enlazan C–A–G–E–D.']},
 {trick:['Orden sobre el mástil: C – A – G – E – D.','Raíz: E y G en la cuerda 6 · A y C en la cuerda 5 · D en la cuerda 4.','La cejilla hace de cejuela: el traste de la cejilla dice qué acorde es.','Mi abierto + cejilla en el 1 = Fa · en el 3 = Sol · en el 5 = La.','Reconoce la forma y sabrás qué escala va en esa zona.']}]},
{id:8,part:3,title:'Progresiones: por qué las canciones funcionan',sub:'Funciones y números romanos',
 lead:'Una progresión es un pequeño viaje: salir de casa, crear tensión y regresar. Entender ese viaje te permite tocar, transportar y hasta componer canciones.',
 blocks:[
 {aim:['Saber qué función cumple cada acorde: reposo, alejamiento o tensión.','Entender por qué el acorde V pide volver al I.','Escribir y leer progresiones con números romanos.','Transportar una progresión a cualquier tonalidad.','Reconocer las progresiones más usadas y el blues de 12 compases.']},
 {step:'Paso 1',t:'Tres funciones: casa, salida y tensión',p:'Los acordes de una tonalidad (lección 5) no son todos iguales: cada uno cumple una <b>función</b>. La <b>tónica</b> (I) es la casa: suena a reposo, a final. La <b>subdominante</b> (IV, y también ii) es salir de casa: se aleja pero sin tensión fuerte. La <b>dominante</b> (V) es la tensión: suena a pregunta y <span class="hl">pide volver</span> a la casa. En Do mayor: Do es casa, Fa es salida, Sol es tensión. Casi todas las canciones combinan estas tres funciones una y otra vez.'},
 {step:'Paso 2',t:'Por qué el V pide volver al I',p:'Recuerda la lección 6: el acorde de V con séptima (Sol7 en Do) tiene un tritono entre Si y Fa, la distancia más tensa. Además su tercera, Si, está a un solo semitono de Do: es la <b>sensible</b>, la nota que «quiere» subir a la tónica. Cuando suena Sol7 y luego Do, Si sube a Do y Fa baja a Mi: la tensión se resuelve. Esa sensación de «llegar» es la <b>cadencia</b>. Por eso las canciones terminan casi siempre con V → I.'},
 {w:'prog'},
 E({id:'8b',t:'Siente la función',min:3,bpm:70,steps:['Toca Do – Fa – Sol y detente en Sol, dejándolo sonar: escucha cómo queda «en el aire».','Ahora resuelve a Do: escucha la sensación de llegar a casa.','Toca Fa – Sol – Lam: es una cadencia rota. El oído esperaba Do y llega Lam, un acorde que comparte dos notas con Do pero suena triste.','Usa el paso a paso (›) si necesitas ver cómo va cada acorde.'],goal:'Explicas por qué Sol pide volver a Do.',fig:chords(ch('C','F','G','C','F','G','Am'))}),
 {key:'Las progresiones se escriben con <b>números romanos</b> porque así valen para cualquier tonalidad: I–IV–V es «uno, cuatro, cinco» en Do (Do–Fa–Sol), en Sol (Sol–Do–Re) o en Mi (Mi–La–Si). Mayúsculas = acorde mayor, minúsculas = menor. <b>Cambia el tono, no el patrón.</b>'},
 {step:'Paso 3',t:'Ejemplo resuelto: transportar I–V–vi–IV',p:'I–V–vi–IV es probablemente la progresión más usada del pop. En <b>Sol mayor</b>: I = Sol, V = Re, vi = Mim, IV = Do → <b>Sol – Re – Mim – Do</b>. Para pasarla a <b>Re mayor</b>, escribe los acordes de Re (Re, Mim, Fa♯m, Sol, La, Sim, Do♯°) y toma los mismos números: I = Re, V = La, vi = Sim, IV = Sol → <b>Re – La – Sim – Sol</b>. En <b>La mayor</b>: La – Mi – Fa♯m – Re. La canción suena igual, solo más aguda o más grave: así se adapta a tu voz.'},
 E({id:'8a',t:'I – V – vi – IV con pista',min:5,steps:['Inicia la pista en Sol: Sol – Re – Mim – Do.','Rasguea con ella cuatro vueltas, cuatro golpes por acorde.','Cambia la tonalidad a Re (Re – La – Sim – Sol) y luego a La (La – Mi – Fa♯m – Re) en el reproductor, y repite.','Mientras tocas, di los números en voz alta: uno, cinco, seis, cuatro.'],goal:'Tocas la misma progresión en tres tonalidades.',track:{k:1,p:'pop',st:'balada',bpm:76}}),
 {check:[['¿Qué función tiene el acorde V?','Dominante: crea tensión y pide volver al I.'],['¿Cuáles son los acordes I, IV y V en Re mayor?','Re, Sol y La.'],['¿Qué es una cadencia rota?','Cuando después del V, en lugar del I, llega el vi.']]},
 {step:'Paso 4',t:'Las progresiones que vas a encontrar en todos lados',p:'Con pocas progresiones se tocan cientos de canciones: <b>I–IV–V</b> (rock and roll, ranchera, folk), <b>I–V–vi–IV</b> (pop), <b>I–vi–IV–V</b> (baladas de los 50 y 60), <b>vi–IV–I–V</b> (la misma que el pop pero empezando en menor: suena más melancólica) y <b>ii–V–I</b> (jazz y bolero). Cuando aprendas una canción nueva, busca cuál de estas tiene escondida: casi siempre hay una.'},
 {step:'Paso 5',t:'El blues de 12 compases',p:'El blues es una progresión fija de 12 compases, la base del rock, el blues y el rock and roll. Usa solo I, IV y V, todos con séptima. El orden: <span class="hl">I I I I · IV IV I I · V IV I V</span>. En La: La7 cuatro compases, Re7 dos, La7 dos, Mi7, Re7, La7 y Mi7. El último compás (V) se llama <b>turnaround</b>: prepara la vuelta al inicio. Cuenta en voz alta los compases las primeras veces; el oído aprende el viaje muy rápido.'},
 E({id:'8c',t:'Blues en La',min:5,steps:['Inicia la pista: blues de 12 compases en La.','Rasguea La7 (x02020), Re7 (xx0212) y Mi7 (020100) siguiendo el cambio.','Cuenta los compases en voz alta: 4 de La7, 2 de Re7, 2 de La7, Mi7, Re7, La7, Mi7.','En la tercera vuelta deja de contar y guíate por el oído.'],goal:'Llegas al final de tres vueltas sin perderte.',track:{k:3,p:'blues',st:'rock',bpm:88}}),
 {step:'Paso 6',t:'De canción a números',p:'El ejercicio más útil de esta lección es convertir canciones que ya tocas a números. Pasos: 1) averigua la tonalidad (casi siempre es el primer o el último acorde); 2) escribe los acordes de esa tonalidad con la tabla de la lección 5; 3) a cada acorde de la canción ponle su número. Ejemplo: una canción con Do – Lam – Fa – Sol está en Do y es I – vi – IV – V. Con eso puedes tocarla en cualquier tono y, sobre todo, empezar a reconocer patrones de oído.'},
 E({id:'8d',t:'Escribe con números',min:5,steps:['Elige una canción que sepas tocar (puedes usar el cancionero).','Escribe sus acordes y averigua su tonalidad: casi siempre es el primero o el último acorde.','Conviértelos a números romanos con la tabla de la lección 5.','Tócala en otra tonalidad usando solo los números.'],goal:'Transportas una canción real sin buscarla en internet.'}),
 {sec:'Sustituciones sencillas',p:'Dos acordes que comparten dos notas pueden reemplazarse: iii sustituye a I (Mi menor y Do mayor comparten Mi y Sol), vi también a I (La menor comparte Do y Mi), ii a IV, y vii° a V. Prueba en I–IV–V–I cambiar el IV por ii y el I final por vi: es otra canción con el mismo viaje.'},
 {box:'Errores comunes',ul:['Creer que una progresión solo funciona en una tonalidad.','Olvidar que vi es menor y su carácter es distinto al de I.','Tocar todos los acordes con el mismo ritmo y volumen: la función se siente con acentos y silencios.','Terminar una canción en V sin querer: suena a pregunta sin respuesta.','Cambiar de acorde sin pensar en la función del siguiente.']},
 {trick:['Tónica: I (también vi, iii) · subdominante: IV, ii · dominante: V, vii°.','V → I: la tensión se resuelve (cadencia).','I–IV–V, I–V–vi–IV, I–vi–IV–V y ii–V–I cubren cientos de canciones.','Blues de 12: I I I I · IV IV I I · V IV I V.','Para transportar: mismos números, otra tonalidad.']}]},
{id:9,part:3,title:'El círculo de quintas y la modulación',sub:'Doce tonalidades en un solo mapa',
 lead:'Las doce tonalidades ordenadas en un reloj: con él sabes qué sostenidos o bemoles lleva cada una, qué acordes van juntos y cómo pasar de una tonalidad a otra.',
 blocks:[
 {aim:['Saber qué es la armadura de una tonalidad (sus sostenidos o bemoles).','Entender por qué cada quinta agrega un sostenido.','Dibujar el círculo de quintas de memoria.','Encontrar la relativa menor de cualquier tonalidad mayor.','Usar el círculo para ver qué acordes combinan y para modular.']},
 {step:'Paso 1',t:'Qué es la armadura',p:'Cada tonalidad mayor usa la receta T T S T T T S (lección 3). Desde Do esa receta cae justo en las teclas blancas: Do mayor no lleva ni sostenidos ni bemoles. Desde cualquier otra nota, la receta obliga a alterar algunas notas. El conjunto de alteraciones fijas de una tonalidad se llama <b>armadura</b>. Ejemplo: Sol mayor siempre lleva <b>Fa♯</b>; Fa mayor siempre lleva <b>Si♭</b>. Conocer la armadura te dice qué notas y qué acordes vas a usar.'},
 {step:'Paso 2',t:'Ejemplo resuelto: de Do a Sol, un sostenido',p:'Aplica la receta desde Sol: Sol (T) La (T) Si (S) Do (T) Re (T) Mi (T) <b>Fa♯</b> (S) Sol. Todas las notas son de Do mayor menos una: el Fa sube a Fa♯, porque el séptimo grado tiene que estar a un semitono de la tónica. Ahora desde Re, que está una quinta arriba de Sol: Re Mi <b>Fa♯</b> Sol La Si <b>Do♯</b> Re. Se conserva Fa♯ y se agrega Do♯. La regla: <span class="hl">cada vez que subes una quinta, la tonalidad nueva conserva los sostenidos y agrega uno más</span>. Al revés, cada vez que bajas una quinta (o subes una cuarta) agregas un bemol: Fa mayor lleva Si♭; Si♭ mayor lleva Si♭ y Mi♭.'},
 {step:'Paso 3',t:'El reloj de las tonalidades',p:'Pon Do arriba, como las 12 de un reloj. Hacia la derecha, de quinta en quinta, cada paso agrega un sostenido: <b>Sol (1♯), Re (2♯), La (3♯), Mi (4♯), Si (5♯), Fa♯ (6♯)</b>. Hacia la izquierda, de cuarta en cuarta, cada paso agrega un bemol: <b>Fa (1♭), Si♭ (2♭), Mi♭ (3♭), La♭ (4♭), Re♭ (5♭), Sol♭ (6♭)</b>. Abajo se juntan: Fa♯ y Sol♭ son la misma tonalidad escrita de dos formas. Eso es el <b>círculo de quintas</b>.'},
 {w:'circle'},
 E({id:'9a',t:'Dibuja el círculo',min:5,steps:['En una hoja, dibuja doce posiciones como un reloj y escribe Do arriba.','Avanza por quintas hacia la derecha: Sol, Re, La, Mi, Si, Fa♯. Junto a cada una escribe cuántos sostenidos lleva (1 a 6).','Avanza por cuartas hacia la izquierda: Fa, Si♭, Mi♭, La♭, Re♭. Escribe cuántos bemoles lleva cada una.','Añade dentro la relativa menor de cada una (paso 4).'],goal:'Dibujas el círculo completo de memoria en menos de dos minutos.'}),
 {key:'Cada tonalidad mayor tiene una <b>relativa menor</b> que usa exactamente las mismas notas y la misma armadura. La encuentras en su <b>sexto grado</b>, o sea <b>tres semitonos abajo</b> de la tónica: Do mayor ↔ La menor, Sol mayor ↔ Mi menor, Re mayor ↔ Si menor, Fa mayor ↔ Re menor. En la guitarra: baja tres trastes desde la tónica mayor.'},
 {step:'Paso 4',t:'Cómo se usa el círculo en la guitarra',p:'Lo más útil del círculo: <b>los acordes de una tonalidad están todos juntos</b> en una rebanada. Para Do mayor, mira Do y sus dos vecinos, Fa (izquierda) y Sol (derecha): son los tres acordes mayores, I, IV y V. Sus relativas menores, Lam, Rem y Mim, son los tres acordes menores, vi, ii y iii. Seis de los siete acordes de la tonalidad están en un solo vistazo. Lo mismo vale para cualquier tonalidad: gira la rebanada.'},
 E({id:'9b',t:'Recorre el círculo con acordes',min:4,bpm:70,steps:['Toca Do – Sol – Re – La – Mi subiendo por quintas, dos golpes cada uno. Usa el paso a paso (›) para ver los dedos y la cejilla de cada acorde.','Regresa por cuartas: Do – Fa – Si♭ – Mi♭ (Si♭ y Mi♭ van con cejilla).','Escucha cómo cada cambio suena natural: cada acorde es el V del que sigue al regresar.','Dilo en voz alta: «uno, dos, tres sostenidos…».'],goal:'Recorres nueve tonalidades sin detenerte.',fig:chords(ch('C','G','D','A','E','C','F','Bb','Eb'),2)}),
 {check:[['¿Cuántos sostenidos tiene La mayor?','Tres (Fa♯, Do♯, Sol♯).'],['¿Cuál es la relativa menor de Sol mayor?','Mi menor (tres semitonos abajo de Sol).'],['¿Qué tonalidad lleva solo un bemol?','Fa mayor (Si♭).'],['¿Cuáles son los acordes mayores de Re mayor según el círculo?','Re y sus vecinos: Sol (IV) y La (V).']]},
 {step:'Paso 5',t:'Modular: cambiar de casa a mitad de la canción',p:'<b>Modular</b> es cambiar de tonalidad dentro de una canción, por ejemplo para que el último coro suene más alto y emocionante. Las tonalidades vecinas en el círculo comparten 6 de sus 7 notas, por eso pasar de Do a Sol o a Fa suena natural. El truco más usado es el <b>acorde pivote</b>: un acorde que existe en las dos tonalidades y sirve de puente. Ejemplo resuelto: La menor es vi en Do mayor y también ii en Sol mayor. Tocas Do – Lam (todavía en Do), y luego Re7 – Sol: el Lam ya se oye como ii de Sol y la casa cambió.'},
 E({id:'9c',t:'Modula con un pivote',min:4,bpm:70,steps:['En Do: Do – Lam – Fa – Sol – Do. Siente que Do es la casa.','Usa Lam como pivote (es vi en Do y ii en Sol): Lam – Re7 – Sol.','Quédate en Sol: Sol – Mim – Do – Re – Sol. Ahora la casa es Sol.','Fíjate en el momento exacto en que el Fa♯ de Re7 te dice que cambiaste de tonalidad.'],goal:'Escuchas el momento en que cambia la casa.',fig:chords(ch('C','Am','F','G','C','Am','D7','G','Em','C','D','G'))}),
 {sec:'Trucos para leer la armadura',p:'Los sostenidos llegan siempre en el mismo orden: <b>Fa, Do, Sol, Re, La, Mi, Si</b>. Los bemoles, al revés: <b>Si, Mi, La, Re, Sol, Do, Fa</b>. Si una canción tiene sostenidos, toma el último y sube un semitono: esa es la tónica mayor (con Fa♯ y Do♯, la tonalidad es Re). Si tiene bemoles, la tónica es el penúltimo bemol (con Si♭, Mi♭ y La♭, la tonalidad es Mi♭); con un solo bemol, la tonalidad es Fa.'},
 {box:'Errores comunes',ul:['Memorizar el círculo sin entender la regla: cada quinta arriba, un sostenido más.','Confundir Fa♯ y Sol♭ mayor: es la misma tonalidad escrita distinto.','Olvidar que la relativa menor comparte armadura con su mayor.','Creer que modular exige un pivote: es un recurso, no la única vía (a veces se cambia de golpe).']},
 {trick:['Derecha (quintas): +1 sostenido por paso · izquierda (cuartas): +1 bemol por paso.','Orden de sostenidos: Fa Do Sol Re La Mi Si · de bemoles: Si Mi La Re Sol Do Fa.','Relativa menor: tres semitonos abajo (Do → La).','I, IV y V son vecinos en el círculo; sus relativas son vi, ii y iii.','Tonalidades vecinas comparten 6 de 7 notas: por eso es fácil modular entre ellas.']}]},
{id:10,part:4,title:'Improvisar con intención',sub:'Cinco cajas y notas objetivo',
 lead:'La escala te da las notas; la intención está en cuáles eliges, cuándo las tocas y dónde terminas.',
 blocks:[
 {aim:['Entender por qué la pentatónica casi nunca suena mal.','Tocar la caja 1 con la digitación correcta y moverla a cualquier tonalidad.','Elegir pentatónica menor o mayor según la canción.','Enlazar cajas para usar todo el mástil.','Construir frases con pregunta, respuesta, silencio y notas objetivo.']},
 {step:'Paso 1',t:'Cinco notas que casi nunca chocan',p:'La <b>pentatónica</b> es una escala de cinco notas (penta = cinco). La <b>menor</b> tiene los grados <b>1 ♭3 4 5 ♭7</b>: en La menor son La, Do, Re, Mi, Sol. Es la escala menor natural sin sus dos notas más delicadas (la 2 y la ♭6), que son las que más chocan con los acordes. Por eso funciona sobre casi cualquier acorde de la tonalidad: es la escala del blues, del rock y de la mayoría de los solos que conoces. Con cinco notas, casi no hay forma de equivocarte.'},
 {step:'Paso 2',t:'La caja 1: la forma básica',p:'En el mástil, la pentatónica forma cinco «cajas». La primera, y la más usada, para La menor está en el traste 5, con la raíz en la cuerda 6 bajo el dedo 1. Por cuerda, de la 6 a la 1: <b>5–8, 5–7, 5–7, 5–7, 5–8, 5–8</b>. Los dedos siguen la regla de un dedo por traste: <span class="hl">dedo 1 en el traste 5 siempre; dedo 3 en el traste 7; dedo 4 en el traste 8</span>. Las raíces (La) están en la cuerda 6 y la 1 en el traste 5, y en la cuerda 4 en el traste 7. Para otra tonalidad, mueve toda la caja: pon el dedo 1 en la raíz de la cuerda 6 (Mi menor: traste 12 o 0; Sol menor: traste 3).'},
 {w:'penta'},
 E({id:'10a',t:'Caja 1 al metrónomo',min:4,bpm:60,steps:['Pentatónica de La menor, caja 1, traste 5. Usa el paso a paso (›) para ver cada nota con su dedo: 1 y 4 en las cuerdas 6, 2 y 1; 1 y 3 en las cuerdas 5, 4 y 3.','Sube y baja una nota por pulso, alternando la púa (abajo, arriba).','Luego dos notas por pulso.','Sube 5 bpm cada vez que salga limpia tres veces seguidas.'],goal:'Tocas la caja a corcheas a 90 bpm.',fig:boxFig(3,'min',1,10)}),
 {key:'La pentatónica mayor de una tonalidad usa <b>las mismas notas</b> que la pentatónica menor de su relativa (tres semitonos abajo). Do mayor (Do Re Mi Sol La) = La menor (La Do Re Mi Sol). Lo único que cambia es la casa. Regla práctica: si la canción está en <b>menor</b>, usa la pentatónica menor de la tónica. Si está en <b>mayor</b> (Sol mayor), usa las cajas de su relativa menor (Mi menor) pero termina tus frases en Sol: suena alegre, como en el country o la ranchera.'},
 {step:'Paso 3',t:'Una escala no es una melodía: frases',p:'Subir y bajar la caja no es improvisar. Una <b>frase</b> es una idea corta: 2 a 5 notas, con un ritmo que se pueda tararear. La técnica más útil es <b>pregunta y respuesta</b>: tocas una frase que termina «abierta» (en una nota que no es la raíz) y luego otra que «contesta» y termina en la raíz. Y el silencio es parte de la música: deja espacio entre frases para que se entiendan. Empieza con muy pocas notas; con tres notas bien usadas se hace un solo.'},
 E({id:'10b',t:'Tres notas, una frase',min:4,steps:['Inicia la pista de blues en La.','Improvisa solo con La (cuerda 6, traste 5), Do (cuerda 6, traste 8) y Re (cuerda 5, traste 5).','Toca dos compases y deja dos de silencio.','Varía el ritmo, no las notas: notas largas, cortas, repetidas, en contratiempo.'],goal:'Tus frases suenan a pregunta y respuesta.',track:{k:3,p:'blues',st:'rock',bpm:84}}),
 {check:[['¿Qué grados tiene la pentatónica menor?','1 ♭3 4 5 ♭7.'],['¿Dónde pones la caja 1 para tocar en Sol menor?','Con el dedo 1 en el traste 3 de la cuerda 6 (Sol).'],['Una canción está en Re mayor. ¿Qué cajas usas?','Las de Si menor (su relativa), terminando las frases en Re.']]},
 {step:'Paso 4',t:'Las cinco cajas cubren todo el mástil',p:'Las cajas se enlazan una tras otra hacia el cuerpo de la guitarra, compartiendo notas: la parte de arriba de la caja 1 es la parte de abajo de la caja 2. En La menor: caja 1 en el traste 5, caja 2 alrededor del 7–10, caja 3 del 9–12, caja 4 del 12–15 y caja 5 del 14–17, y luego vuelve la caja 1 en el traste 17. No necesitas las cinco hoy: con la caja 1 y la 2 ya cubres casi todo lo que se toca en un solo de rock. Para pasar de una a otra, desliza un dedo (slide) por una cuerda.'},
 E({id:'10c',t:'Une la caja 1 y la 2',min:4,bpm:60,steps:['Sube por la caja 1 hasta la cuerda 3.','En la cuerda 3, desliza el dedo 3 del traste 7 al 9 y sigue en la caja 2.','Baja por la caja 2 y regresa a la 1 deslizando otra vez.','Usa el paso a paso (›) para ver el recorrido completo de las dos cajas.'],goal:'Cruzas de una caja a otra sin detenerte.',fig:boxFig(3,'min',0,12,[5,10])}),
 {step:'Paso 5',t:'Notas objetivo: apuntarle al acorde',p:'Aquí está la «intención»: las notas de la escala no pesan igual en todo momento. Sobre cada acorde, sus propias notas (raíz, tercera, quinta) suenan firmes; las demás suenan a camino. La técnica de <b>notas objetivo</b> es planear tus frases para que en los tiempos fuertes, y sobre todo al final, caigas en una nota del acorde que está sonando. Ejemplo: sobre Lam termina en La o Do; cuando cambia a Fa, termina en Fa o La. El público no sabe teoría, pero escucha que tu solo «va con la canción».'},
 E({id:'10d',t:'Apunta al acorde',min:5,steps:['Inicia la pista en La menor: Lam – Fa – Do – Sol.','Termina cada frase en la raíz del acorde que suena: La, Fa, Do, Sol.','Cuando lo domines, termina en su tercera: Do sobre Lam, La sobre Fa, Mi sobre Do, Si sobre Sol (Fa y Si no están en la pentatónica: tómalas prestadas de la escala menor).','Escucha cómo cambia el color de cada final.'],goal:'Cada final de frase coincide con el acorde.',track:{k:3,p:'menor',st:'balada',bpm:72}}),
 {step:'Paso 6',t:'Sabor: blue note y técnicas',p:'Para que suene a guitarra y no a ejercicio, usa: <b>slides</b> (deslizar a la nota), <b>ligados</b> (pegar dos notas con un solo ataque, hammer-on y pull-off) y <b>bends</b> (empujar la cuerda para subir la nota; el más común es subir el 4 de la caja hasta que suene como el 5). La <b>blue note</b> es la ♭5 en la pentatónica menor (en La, el Mi♭): una nota de paso, de tensión, que se toca rápido y se resuelve en la 4 o la 5. Úsala como sal, no como plato fuerte.'},
 E({id:'10e',t:'Pentatónica mayor en ranchera',min:5,steps:['Inicia la pista ranchera en Sol.','Toca la pentatónica mayor de Sol: las mismas cajas que Mi menor, con la caja 1 en el traste 12 (o en las cuerdas al aire, traste 0). Termina tus frases en Sol.','Prueba terceras en pares, como en un requinto: Sol–Si, La–Do, Si–Re, Do–Mi, Re–Fa♯ (notas de la escala de Sol mayor, tocadas juntas en las cuerdas 2 y 3).','Termina con Si–Re sobre el acorde de Sol.'],goal:'Tu melodía suena alegre y termina en Sol.',track:{k:1,p:'ranchera',st:'ranchera',bpm:120}}),
 {box:'Errores comunes',ul:['Tocar la caja de arriba abajo sin frases: una escala no es una melodía.','Llenar todo de notas: el silencio deja respirar el solo.','Usar siempre la caja 1: enlaza al menos dos.','Olvidar el acorde de fondo: la intención nace de él.','Abusar de la blue note: úsala de paso, no para terminar.']},
 {trick:['Pentatónica menor: 1 ♭3 4 5 ♭7 · mayor: 1 2 3 5 6.','Caja 1: dedo 1 en la raíz de la cuerda 6.','Mayor y su relativa menor comparten las mismas cajas; cambia la nota donde terminas.','Tiempo fuerte y final de frase = nota del acorde.','Blue note: ♭5 en la menor, de paso.','Pregunta (termina abierta) y respuesta (termina en la raíz).']}]},
{id:11,part:4,title:'Sacar de oído y componer lo tuyo',sub:'Método para oír y para crear',
 lead:'Sacar una canción de oído no es un don: es un método en el que cada paso reduce las opciones. Y componer es usar ese mismo conocimiento al revés.',
 blocks:[
 {aim:['Encontrar la tónica de cualquier canción.','Decidir si una canción está en mayor o en menor.','Sacar la progresión de acordes siguiendo el bajo.','Usar lo que sabes de tonalidades para adivinar los acordes probables.','Componer un motivo y desarrollarlo sobre una progresión.']},
 {step:'Paso 1',t:'Por qué funciona el método',p:'Sacar de oído parece magia porque intentamos adivinar todo a la vez. El truco es ir de lo general a lo particular. Una canción en una tonalidad mayor usa, casi siempre, solo 6 o 7 acordes (lección 5), y de esos casi siempre usa I, IV, V y vi. Así que si encuentras <b>la tónica</b> y sabes si es <b>mayor o menor</b>, ya pasaste de 24 acordes posibles a unos 4 o 5 probables. Cada paso reduce las opciones.'},
 {step:'Paso 2',t:'Encontrar la tónica',p:'La tónica es la nota donde la canción <b>descansa</b>: suele ser la última nota del coro y la que suena al final de la canción. Tararéala y búscala en la guitarra: toca notas en la cuerda 6 o 5 (empieza por las naturales) hasta que una suene igual a lo que tarareas, o hasta que suene «a casa» cuando la tocas encima de la canción. Si dudas entre dos notas, quédate con la que suena bien al final de una frase. Con práctica esto toma segundos.'},
 E({id:'11a',t:'Encuentra la tónica',min:4,steps:['Pon una canción que te guste.','Tararea la nota donde descansa el final del coro (o la última nota de la canción).','Búscala en la cuerda 6 o 5 tocando nota por nota hasta que coincida.','Comprueba: toca esa nota encima de la canción en distintos momentos. Debe sonar bien casi siempre.'],goal:'Encuentras la tónica de una canción en menos de un minuto.'}),
 {step:'Paso 3',t:'¿Mayor o menor?',p:'Con la tónica encontrada, la pregunta es si la canción es mayor (alegre) o menor (triste). La diferencia está en la tercera (lecciones 2 y 5). Toca la tónica y luego <b>4 trastes arriba</b> (tercera mayor) mientras suena la canción; después <b>3 trastes arriba</b> (tercera menor). Una de las dos choca y la otra encaja. Ejemplo: si la tónica es La y encaja Do (3 trastes), la canción está en La menor; si encaja Do♯ (4 trastes), en La mayor.'},
 E({id:'11b',t:'¿Mayor o menor?',min:3,steps:['Sobre la tónica que encontraste, toca la tercera mayor (+4 trastes en la misma cuerda) mientras suena la canción.','Luego la tercera menor (+3 trastes).','Decide cuál encaja con la canción y cuál choca.','Escribe: «La canción está en ___ mayor / menor».'],goal:'Sabes si la canción está en tonalidad mayor o menor.'}),
 {key:'Con la tonalidad ya sabes cuáles son los acordes probables. En <b>mayor</b>: I, IV, V y vi (en Sol: Sol, Do, Re, Mim). En <b>menor</b>: i, iv, v (o V) y los mayores ♭III, ♭VI y ♭VII (en La menor: Lam, Rem, Mim o Mi, Do, Fa y Sol). Empieza probando esos; el 90 % de las canciones populares no usan otros.'},
 {step:'Paso 4',t:'Seguir el bajo para sacar la progresión',p:'Los acordes cambian, pero el oído no siempre los distingue. Lo que sí se escucha fácil es <b>el bajo</b>, la nota más grave, que casi siempre toca la raíz del acorde. Escucha solo eso en cada cambio, búscalo en las cuerdas 6 y 5, y anótalo. Luego decide si cada acorde es mayor o menor probando las dos versiones. Ejemplo: en Sol mayor escuchas que el bajo va Sol → Re → Mi → Do; con la lista del recuadro de arriba, eso es <b>Sol – Re – Mim – Do</b> (I – V – vi – IV, la progresión de la lección 8).'},
 E({id:'11c',t:'Saca el bajo',min:5,steps:['Escucha solo las notas más graves en cada cambio de acorde de una estrofa.','Búscalas en las cuerdas 6 y 5 y anótalas en orden.','Decide si cada acorde es mayor o menor: prueba ambos y quédate con el que encaja.','Escríbelas como grados de la tonalidad: así sale la progresión.'],goal:'Escribes la progresión de una estrofa.'}),
 {check:[['¿Por qué conviene encontrar primero la tónica?','Porque con la tonalidad ya sabes qué acordes son probables y descartas casi todos los demás.'],['Tónica Mi, y encaja Sol (3 trastes arriba). ¿En qué tonalidad está?','Mi menor.'],['¿Qué nota del acorde suele tocar el bajo?','La raíz.']]},
 {step:'Paso 5',t:'Componer: un motivo es suficiente para empezar',p:'Componer es lo mismo pero al revés. Necesitas tres cosas: una <b>progresión</b> (lección 8, por ejemplo Sol – Re – Mim – Do), una <b>escala</b> (la de la tonalidad, o su pentatónica) y un <b>motivo</b>: una idea corta de 2 a 4 notas con un ritmo claro. Lo que hace que una melodía se recuerde no es tener muchas ideas, es <b>repetir</b> una idea y <b>variarla</b>: repítela igual, luego cambia la última nota, luego empiézala en otra nota del acorde siguiente. Así nacen casi todos los coros que conoces.'},
 {w:'sketch'},
 E({id:'11d',t:'Compón un motivo',min:5,steps:['Arma en el boceto una melodía de ocho pasos y escúchala. Usa notas de la escala de Sol mayor.','Inicia la pista en Sol y toca tu melodía en la guitarra sobre ella.','Repítela cambiando solo la última nota: una vez termina en Sol (cierra) y otra en Re (queda abierta).','Pon las dos juntas: pregunta y respuesta.'],goal:'Tienes una idea de ocho pasos que puedes tocar de memoria.',track:{k:1,p:'pop',st:'balada',bpm:76}}),
 {step:'Paso 6',t:'Escúchate: grabar es la mitad del trabajo',p:'Mientras tocas, tu atención está en los dedos; por eso no oyes del todo lo que suena. Grábate (con la grabadora de la app o con tu teléfono) y escúchate <b>al día siguiente</b>, con oídos frescos. Vas a notar qué frases funcionan, cuáles se repiten demasiado y dónde se te va el tiempo. Los músicos que más rápido mejoran son los que se graban seguido, aunque no les guste cómo suenan al principio.'},
 E({id:'11e',t:'Graba y compara',min:5,steps:['Graba con la grabadora de la app (o tu teléfono) ocho compases improvisados sobre una pista.','Escúchalos al día siguiente, sin la guitarra en la mano.','Anota una frase que repetirías y una que cambiarías.','Vuelve a grabar con ese cambio y compara las dos versiones.'],goal:'Tienes tres grabaciones en una semana.'}),
 {box:'Errores comunes',ul:['Empezar por el solo: busca primero la tónica y los acordes.','Tratar de adivinar todos los acordes a la vez: sigue el método paso a paso.','Confiar solo en la vista: cierra los ojos y canta.','No grabarte: el oído mejora al comparar.','Componer sin progresión: la melodía necesita un soporte.']},
 {trick:['Tónica primero, siempre: la nota donde descansa la canción.','Mayor o menor: prueba la tercera (+4 o +3 trastes).','Acordes probables en mayor: I, IV, V, vi.','El bajo casi siempre toca la raíz: síguelo.','Motivo corto: repetir, variar, mover.','Grábate y escúchate al día siguiente.']}]}
];
const PARTS2=[{n:1,t:'Ver',m:[1,2]},{n:2,t:'Construir',m:[3,4,5,6]},{n:3,t:'Conectar',m:[7,8,9]},{n:4,t:'Crear',m:[10,11]}];
const ALLEX=[];LESSONS.forEach(l=>l.blocks.forEach(b=>{if(b.ex){b.ex.lesson=l.id;ALLEX.push(b.ex)}}));
const GLOS=[
['Nota','Cada uno de los 12 sonidos distintos: Do, Re, Mi, Fa, Sol, La, Si y sus sostenidos.'],
['Semitono','La distancia mínima: un traste.'],['Tono','Dos semitonos: dos trastes.'],
['Intervalo','La distancia entre dos notas.'],['Octava','La misma nota, doce semitonos más arriba.'],
['Escala','Un conjunto de notas ordenadas según una fórmula.'],['Tonalidad','Una escala con sus acordes y un centro de reposo.'],
['Grado','El número de una nota dentro de la escala (1 a 7).'],['Tónica','El grado 1: la nota de reposo.'],
['Dominante','El grado 5: crea tensión que pide volver a la tónica.'],['Subdominante','El grado 4: se aleja del reposo.'],
['Acorde','Tres o más notas que suenan juntas, apiladas en terceras.'],['Tríada','Acorde de tres notas: raíz, tercera y quinta.'],
['Séptima','Una cuarta nota sobre la tríada, a distancia de séptima.'],['Tensión','Nota de color (9, 11, 13) añadida a un acorde.'],
['Modo','La misma escala mayor empezando por otro grado.'],['Progresión','Una sucesión de acordes.'],
['Cadencia','Una fórmula de acordes que cierra o suspende una frase.'],['Cejilla','Dedo (o capo) que presiona varias cuerdas en un mismo traste.'],
['Pentatónica','Escala de cinco notas, base del blues y el rock.'],['Armadura','Los sostenidos o bemoles fijos de una tonalidad.'],
['Modulación','Cambio de una tonalidad a otra dentro de una canción.'],['BPM','Pulsos por minuto: la velocidad del metrónomo.'],['Caja','Una zona de la pentatónica que cabe bajo la mano sin moverla.']];
